/* ===== migrated source: export-images.js ===== */
/* ══════════════════════════════════════════════════════════════
   Export Assistant Message to Phone-Screen Images (9:16, 1080×1920)
   ══════════════════════════════════════════════════════════════ */

const ExportImages = (() => {
  // ── Lazy-load html2canvas (199KB) on first use ─────────────
  let _html2canvasReady = null;
  function _ensureHtml2Canvas() {
    if (html2canvas) return Promise.resolve();
    if (_html2canvasReady) return _html2canvasReady;
    _html2canvasReady = loadHtml2Canvas().then((module) => { html2canvas = module; });
    return _html2canvasReady;
  }

  // ── Constants ──────────────────────────────────────────────
  const PAGE_W = 1080;
  const PAGE_H = 1920;
  const PAD_X = 72;
  const PAD_TOP = 100;
  const PAD_BOT = 120; // extra room for page number footer
  const CONTENT_W = PAGE_W - PAD_X * 2;
  const CONTENT_H = PAGE_H - PAD_TOP - PAD_BOT;
  const SCALE = 2; // render at 2x for crisp text

  // ── Theme colors (dark) ────────────────────────────────────
  const THEME = {
    bg:       '#0a0a0c',
    bgCard:   '#111115',
    text:     '#e8e8ed',
    textSec:  '#9898a8',
    textTer:  '#6a6a7a',
    accent:   '#6e56cf',
    border:   '#2a2a35',
    codeBg:   '#111115',
    blockBg:  '#1a1a21',
  };

  /**
   * Main entry: export an assistant Turn by stable identity.
   */
  async function exportMessage(turnId) {
    const conv = getActiveConv();
    if (!conv) return;
    const turn = runtimeScope.ConversationTurnStore?.ensureRuntimeStore?.(conv.id)
      ?.getState?.().turnsById?.[turnId];
    if (!turn || !['assistant', 'planner'].includes(turn.actor)) return;

    // Show progress toast
    const toastId = _showProgress('Preparing export…', 0);

    try {
      // 1. Get the rendered HTML from the DOM
      const msgEl = Array.from(document.querySelectorAll('[data-turn-id]'))
        .find(node => node.dataset.turnId === turnId);
      if (!msgEl) throw new Error('Message element not found');

      const mdEl = msgEl.querySelector('.md-content');
      if (!mdEl) throw new Error('No content to export');

      // 2. Build the offscreen container
      const { container, contentDiv } = _createOffscreenContainer();
      document.body.appendChild(container);

      // 3. Clone content into the measurement container
      const clonedContent = mdEl.cloneNode(true);
      // Remove any user-content class (it changes white-space handling)
      clonedContent.classList.remove('user-content');
      contentDiv.appendChild(clonedContent);

      // 4. Wait for any images/fonts to settle
      await new Promise(r => setTimeout(r, 200));

      // 5. Measure & split into pages
      const pages = _splitIntoPages(contentDiv);
      _updateProgress(toastId, `Rendering ${pages.length} page(s)…`, 10);

      // 6. Render each page to canvas
      const images = [];
      for (let i = 0; i < pages.length; i++) {
        const pct = 10 + Math.round((i / pages.length) * 80);
        _updateProgress(toastId, `Rendering page ${i + 1}/${pages.length}…`, pct);

        const canvas = await _renderPage(contentDiv, pages[i], i, pages.length);
        images.push(canvas);
      }

      // 7. Download
      _updateProgress(toastId, 'Downloading…', 95);
      await _downloadImages(images);

      // 8. Cleanup
      document.body.removeChild(container);
      _updateProgress(toastId, `✅ Exported ${images.length} image(s)`, 100);
      setTimeout(() => _removeProgress(toastId), 2500);

    } catch (err) {
      console.error('[ExportImages] Error:', err);
      _updateProgress(toastId, `❌ Export failed: ${err.message}`, -1);
      setTimeout(() => _removeProgress(toastId), 4000);
    }
  }

  // ── Create offscreen measuring/rendering container ─────────
  function _createOffscreenContainer() {
    const container = document.createElement('div');
    container.id = 'export-offscreen';
    container.style.cssText = `
      position: fixed; left: -9999px; top: 0; z-index: -1;
      width: ${CONTENT_W}px; overflow: hidden;
      background: ${THEME.bg}; color: ${THEME.text};
      font-family: 'Plus Jakarta Sans', -apple-system, sans-serif;
    `;

    const contentDiv = document.createElement('div');
    contentDiv.className = 'md-content export-md-content';
    contentDiv.style.cssText = `
      width: ${CONTENT_W}px;
      font-size: 17px;
      line-height: 1.8;
      color: ${THEME.text};
      overflow: visible;
    `;

    container.appendChild(contentDiv);
    return { container, contentDiv };
  }

  // ── Split content into page ranges ─────────────────────────
  // Returns array of { startY, endY } for each page slice
  function _splitIntoPages(contentDiv) {
    const totalHeight = contentDiv.scrollHeight;
    if (totalHeight <= CONTENT_H) {
      return [{ startY: 0, endY: totalHeight }];
    }

    const pages = [];
    let currentY = 0;

    while (currentY < totalHeight) {
      let endY = currentY + CONTENT_H;
      if (endY >= totalHeight) {
        pages.push({ startY: currentY, endY: totalHeight });
        break;
      }

      // Try to find a good break point (between block elements)
      const breakY = _findBreakPoint(contentDiv, currentY, endY);
      pages.push({ startY: currentY, endY: breakY });
      currentY = breakY;
    }

    return pages;
  }

  // ── Find a good break point near targetY ───────────────────
  function _findBreakPoint(contentDiv, startY, targetY) {
    // Walk all top-level children and find the last one that ends before targetY
    const children = contentDiv.children;
    let bestBreak = targetY;

    // Check all descendant elements for break points
    const allElements = contentDiv.querySelectorAll('p, h1, h2, h3, h4, li, pre, blockquote, table, hr, .code-header, .katex-display, br');
    let lastGoodBreak = startY + CONTENT_H * 0.3; // minimum 30% fill

    for (const el of allElements) {
      const rect = el.getBoundingClientRect();
      const containerRect = contentDiv.getBoundingClientRect();
      const elBottom = rect.bottom - containerRect.top;
      const elTop = rect.top - containerRect.top;

      // We want elements that end within our page range
      if (elBottom > startY && elBottom <= targetY) {
        // Break after this element
        if (elBottom > lastGoodBreak) {
          lastGoodBreak = elBottom;
        }
      }
      // If element starts before target but extends past, break before it
      if (elTop > startY + CONTENT_H * 0.3 && elTop <= targetY && elBottom > targetY) {
        if (elTop > startY + CONTENT_H * 0.2) {
          bestBreak = elTop;
          return bestBreak;
        }
      }
    }

    return lastGoodBreak > startY ? lastGoodBreak : targetY;
  }

  // ── Render a single page to canvas ─────────────────────────
  async function _renderPage(contentDiv, pageRange, pageIdx, totalPages) {
    const { startY, endY } = pageRange;
    const sliceH = endY - startY;

    // Create a wrapper with exact page dimensions
    const pageDiv = document.createElement('div');
    pageDiv.style.cssText = `
      width: ${PAGE_W}px;
      height: ${PAGE_H}px;
      background: ${THEME.bg};
      position: fixed;
      left: -9999px;
      top: 0;
      z-index: -1;
      overflow: hidden;
    `;

    // ── Decorative header gradient bar ──
    const headerBar = document.createElement('div');
    headerBar.style.cssText = `
      position: absolute; top: 0; left: 0; right: 0; height: 4px;
      background: linear-gradient(90deg, ${THEME.accent}, #a78bfa, #6e56cf);
    `;
    pageDiv.appendChild(headerBar);

    // ── Page number / branding (top-right) ──
    if (totalPages > 1) {
      const pageLabel = document.createElement('div');
      pageLabel.style.cssText = `
        position: absolute; top: 24px; right: ${PAD_X}px;
        font-size: 13px; color: ${THEME.textTer};
        font-family: 'JetBrains Mono', monospace;
        letter-spacing: 0.05em;
      `;
      pageLabel.textContent = `${pageIdx + 1} / ${totalPages}`;
      pageDiv.appendChild(pageLabel);
    }

    // ── Brand label (top-left) ──
    const brand = document.createElement('div');
    brand.style.cssText = `
      position: absolute; top: 22px; left: ${PAD_X}px;
      font-size: 14px; font-weight: 700; letter-spacing: -0.02em;
      background: linear-gradient(135deg, ${THEME.accent}, #a78bfa);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      font-family: 'Plus Jakarta Sans', -apple-system, sans-serif;
    `;
    brand.textContent = '✦ Claude';
    pageDiv.appendChild(brand);

    // ── Content viewport ──
    const viewport = document.createElement('div');
    viewport.style.cssText = `
      position: absolute;
      left: ${PAD_X}px;
      top: ${PAD_TOP}px;
      width: ${CONTENT_W}px;
      height: ${CONTENT_H}px;
      overflow: hidden;
    `;

    // Clone the full content and offset it
    const contentClone = contentDiv.cloneNode(true);
    contentClone.style.cssText = `
      position: absolute;
      top: ${-startY}px;
      left: 0;
      width: ${CONTENT_W}px;
      font-size: 17px;
      line-height: 1.8;
      color: ${THEME.text};
    `;
    viewport.appendChild(contentClone);
    pageDiv.appendChild(viewport);

    // ── Footer watermark ──
    const footer = document.createElement('div');
    footer.style.cssText = `
      position: absolute;
      bottom: 32px;
      left: 0; right: 0;
      text-align: center;
      font-size: 11px;
      color: ${THEME.textTer};
      font-family: 'JetBrains Mono', monospace;
      opacity: 0.5;
    `;
    footer.textContent = 'Generated by Tofu';
    pageDiv.appendChild(footer);

    // ── Bottom gradient bar (mirror of top) ──
    const footerBar = document.createElement('div');
    footerBar.style.cssText = `
      position: absolute; bottom: 0; left: 0; right: 0; height: 3px;
      background: linear-gradient(90deg, #a78bfa, ${THEME.accent});
      opacity: 0.5;
    `;
    pageDiv.appendChild(footerBar);

    document.body.appendChild(pageDiv);

    // Lazy-load & use html2canvas to render
    await _ensureHtml2Canvas();
    const canvas = await html2canvas(pageDiv, {
      width: PAGE_W,
      height: PAGE_H,
      scale: SCALE,
      backgroundColor: THEME.bg,
      useCORS: true,
      logging: false,
      // Ensure fonts are rendered
      onclone: (doc) => {
        // Copy computed styles for code blocks, etc.
        const styles = doc.querySelectorAll('style, link[rel="stylesheet"]');
        // html2canvas handles this automatically
      }
    });

    document.body.removeChild(pageDiv);
    return canvas;
  }

  // ── Download images ────────────────────────────────────────
  async function _downloadImages(canvases) {
    const timestamp = new Date().toISOString().slice(0, 19).replace(/[T:]/g, '-');
    const prefix = `chat-export-${timestamp}`;

    if (canvases.length === 1) {
      // Single image — direct download
      const blob = await _canvasToBlob(canvases[0]);
      _downloadBlob(blob, `${prefix}.png`);
    } else {
      // Multiple images — download individually with slight delay
      for (let i = 0; i < canvases.length; i++) {
        const blob = await _canvasToBlob(canvases[i]);
        _downloadBlob(blob, `${prefix}-${String(i + 1).padStart(2, '0')}.png`);
        // Small delay to avoid browser throttling
        if (i < canvases.length - 1) {
          await new Promise(r => setTimeout(r, 300));
        }
      }
    }
  }

  function _canvasToBlob(canvas) {
    return new Promise(resolve => {
      canvas.toBlob(blob => resolve(blob), 'image/png');
    });
  }

  // Synchronous blob creation for preview (avoids async per-card)
  function _canvasToBlobSync(canvas) {
    try {
      const dataUrl = canvas.toDataURL('image/png');
      const parts = dataUrl.split(',');
      const mime = parts[0].match(/:(.*?);/)[1];
      const bstr = atob(parts[1]);
      const n = bstr.length;
      const u8 = new Uint8Array(n);
      for (let i = 0; i < n; i++) u8[i] = bstr.charCodeAt(i);
      return new Blob([u8], { type: mime });
    } catch {
      return null;
    }
  }

  function _downloadBlob(blob, filename) {
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    a.style.display = 'none';
    document.body.appendChild(a);
    a.click();
    setTimeout(() => {
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    }, 100);
  }

  // ── Progress toast helpers ─────────────────────────────────
  let _toastCounter = 0;

  function _showProgress(text, pct) {
    const id = `export-progress-${++_toastCounter}`;
    const el = document.createElement('div');
    el.id = id;
    el.className = 'export-progress-toast';
    el.innerHTML = `
      <div class="export-progress-icon">${Icon('image', 18)}</div>
      <div class="export-progress-body">
        <div class="export-progress-text">${text}</div>
        <div class="export-progress-bar-wrap">
          <div class="export-progress-bar-fill" style="width:${Math.max(pct, 0)}%"></div>
        </div>
      </div>
    `;
    const container = document.getElementById('toastContainer');
    if (container) container.appendChild(el);
    return id;
  }

  function _updateProgress(id, text, pct) {
    const el = document.getElementById(id);
    if (!el) return;
    const textEl = el.querySelector('.export-progress-text');
    const barEl = el.querySelector('.export-progress-bar-fill');
    if (textEl) textEl.textContent = text;
    if (barEl) barEl.style.width = `${Math.max(pct, 0)}%`;
    if (pct >= 100 || pct < 0) {
      el.classList.add(pct >= 100 ? 'done' : 'error');
    }
  }

  function _removeProgress(id) {
    const el = document.getElementById(id);
    if (el) {
      el.style.opacity = '0';
      el.style.transform = 'translateX(100%)';
      setTimeout(() => el.remove(), 300);
    }
  }

  // ── Preview modal (optional — shows all pages before download) ──
  async function exportMessageWithPreview(turnId) {
    const conv = getActiveConv();
    if (!conv) return;
    const turn = runtimeScope.ConversationTurnStore?.ensureRuntimeStore?.(conv.id)
      ?.getState?.().turnsById?.[turnId];
    if (!turn || !['assistant', 'planner'].includes(turn.actor)) return;

    const toastId = _showProgress('Preparing preview…', 0);

    try {
      const msgEl = Array.from(document.querySelectorAll('[data-turn-id]'))
        .find(node => node.dataset.turnId === turnId);
      if (!msgEl) throw new Error('Message element not found');
      const mdEl = msgEl.querySelector('.md-content');
      if (!mdEl) throw new Error('No content to export');

      const { container, contentDiv } = _createOffscreenContainer();
      document.body.appendChild(container);

      const clonedContent = mdEl.cloneNode(true);
      clonedContent.classList.remove('user-content');
      contentDiv.appendChild(clonedContent);
      await new Promise(r => setTimeout(r, 200));

      const pages = _splitIntoPages(contentDiv);
      _updateProgress(toastId, `Rendering ${pages.length} page(s)…`, 10);

      const canvases = [];
      for (let i = 0; i < pages.length; i++) {
        const pct = 10 + Math.round((i / pages.length) * 80);
        _updateProgress(toastId, `Rendering page ${i + 1}/${pages.length}…`, pct);
        const canvas = await _renderPage(contentDiv, pages[i], i, pages.length);
        canvases.push(canvas);
      }

      document.body.removeChild(container);
      _updateProgress(toastId, '✅ Preview ready', 100);
      setTimeout(() => _removeProgress(toastId), 1500);

      // Show preview modal
      _showPreviewModal(canvases);

    } catch (err) {
      console.error('[ExportImages] Error:', err);
      _updateProgress(toastId, `❌ Export failed: ${err.message}`, -1);
      setTimeout(() => _removeProgress(toastId), 4000);
    }
  }

  let _previewModalEscHandler = null;
  function _showPreviewModal(canvases) {
    // Remove any existing modal
    const existing = document.getElementById('export-preview-modal');
    if (existing) {
      // Revoke any old blob URLs to free memory
      existing.querySelectorAll('img[src^="blob:"]').forEach(img => URL.revokeObjectURL(img.src));
      existing.remove();
    }
    if (_previewModalEscHandler) {
      document.removeEventListener('keydown', _previewModalEscHandler);
      _previewModalEscHandler = null;
    }

    const overlay = document.createElement('div');
    overlay.id = 'export-preview-modal';
    overlay.className = 'export-preview-overlay';

    // Track blob URLs so we can revoke on close
    const blobUrls = [];
    function _cleanup() {
      blobUrls.forEach(u => URL.revokeObjectURL(u));
      blobUrls.length = 0;
      overlay.remove();
      document.removeEventListener('keydown', escHandler);
      if (_previewModalEscHandler === escHandler) _previewModalEscHandler = null;
    }

    overlay.onclick = (e) => {
      if (e.target === overlay) _cleanup();
    };

    // ── Toolbar (matches CSS .epv-toolbar) ──
    const toolbar = document.createElement('div');
    toolbar.className = 'epv-toolbar';
    toolbar.innerHTML = `
      <span style="font-size:15px;display:flex;align-items:center;gap:6px">
        ${Icon('image', 16)} <strong>Export Preview</strong>
        <span style="opacity:0.6;font-weight:400">${canvases.length} page${canvases.length > 1 ? 's' : ''}</span>
      </span>
      <button class="primary" id="exportDownloadAll">
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="vertical-align:-2px">
          <path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/>
          <polyline points="7 10 12 15 17 10"/>
          <line x1="12" y1="15" x2="12" y2="3"/>
        </svg>
        Download All
      </button>
      <button id="exportCloseBtn">✕ Close</button>
    `;
    overlay.appendChild(toolbar);

    // ── Pages grid (matches CSS .epv-grid > .epv-card) ──
    const grid = document.createElement('div');
    grid.className = 'epv-grid';

    canvases.forEach((canvas, i) => {
      const card = document.createElement('div');
      card.className = 'epv-card';

      // Use blob URL instead of data URL — far less memory pressure
      const img = document.createElement('img');
      const blob = _canvasToBlobSync(canvas);
      if (blob) {
        const blobUrl = URL.createObjectURL(blob);
        blobUrls.push(blobUrl);
        img.src = blobUrl;
      } else {
        // Fallback: toDataURL (synchronous but heavier)
        img.src = canvas.toDataURL('image/png');
      }
      img.alt = `Page ${i + 1}`;
      img.loading = 'lazy';

      const label = document.createElement('div');
      label.className = 'epv-label';
      label.innerHTML = `
        <span>Page ${i + 1}</span>
        <button class="epv-card-dl" data-idx="${i}" title="Download this page">
          <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
            <path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/>
            <polyline points="7 10 12 15 17 10"/>
            <line x1="12" y1="15" x2="12" y2="3"/>
          </svg>
        </button>
      `;

      card.appendChild(img);
      card.appendChild(label);
      grid.appendChild(card);
    });

    overlay.appendChild(grid);
    document.body.appendChild(overlay);

    // Event listeners
    document.getElementById('exportCloseBtn').onclick = () => _cleanup();
    document.getElementById('exportDownloadAll').onclick = async () => {
      await _downloadImages(canvases);
      showToast('✅', 'Downloaded', `${canvases.length} image(s) saved`);
    };

    // Individual page download
    grid.querySelectorAll('.epv-card-dl').forEach(btn => {
      btn.onclick = async (e) => {
        e.stopPropagation();
        const i = parseInt(btn.dataset.idx);
        const timestamp = new Date().toISOString().slice(0, 19).replace(/[T:]/g, '-');
        const blob = await _canvasToBlob(canvases[i]);
        _downloadBlob(blob, `chat-export-${timestamp}-${String(i + 1).padStart(2, '0')}.png`);
      };
    });

    // ESC to close
    const escHandler = (e) => {
      if (e.key === 'Escape') _cleanup();
    };
    _previewModalEscHandler = escHandler;
    document.addEventListener('keydown', escHandler);
  }

  // Public API
  return { exportMessage, exportMessageWithPreview };
})();
/* ===== migrated source: artifacts.js ===== */
/* artifacts.js — Retained right-side panel bridge for published artifacts.
 *
 * Backend: lib/artifacts/* persists each artifact to the chat_artifacts
 * table.  Producers (write_file post-hook + inline scanner) call
 * create_artifact + emit a metadata-only "artifact" SSE event.  This
 * module:
 *
 *   1. Normalizes artifact metadata into a presentation-only read model,
 *      joined to authoritative Turns through stable task/turn identity.
 *   2. ConversationSurface renders typed artifact blocks; clicking a chip
 *      emits an open-artifact intent back to this panel.
 *   3. Fetches /api/artifacts/<id>/raw lazily on open and renders it:
 *        markdown → renderMarkdown() (DOMPurify-cleaned, see core.js)
 *        html     → <iframe sandbox srcdoc>  (NO scripts by default)
 *        svg      → script-blocked document iframe
 *        file     → typed inert metadata + server-authorized download controls
 *
 * Security invariants — see lib/artifacts/__init__.py and routes/artifacts.py.
 *   • NEVER innerHTML model HTML into the main document.
 *   • Iframe must NOT have allow-scripts unless the user explicitly opts in
 *     (and we then drop allow-same-origin to keep the spec-safe combo).
 *   • The /raw endpoint already ships a strict CSP — this is defense in depth.
 */

// Temporary lexical presenters; remove with the retained artifact-panel migration.
import { renderPublishedFile, renderScriptWarning } from '../rich-response/artifact-delivery';
import { mountArtifactReview } from '../rich-response/artifact-review';

(function () {
  "use strict";

  // ── Module state ────────────────────────────────────────────────────
  // Presentation metadata is conv-scoped, never an authorization receipt.
  // Only the active body is retained; close/switch releases multi-MiB source.
  const _metaCache = new Map();    // id → meta dict
  const _contentCache = new Map(); // at most one active id → raw string
  // A newer snapshot hint must win over an older metadata request that settles
  // late. Weak keys keep the fence tied to the catalog shell lifecycle.
  const _hydrateEpoch = new WeakMap();
  // Background snapshots may arrive before a Surface exists. Retain only
  // their optional hint; the existing mount lifecycle triggers the owned read.
  const _artifactHints = new WeakMap();

  // The currently open artifact (if any), so SSE updates can refresh.
  let _activeId = null;
  let _disposeReview = null;
  let _openEpoch = 0;

  // Per-session script-allow consent (NOT persisted).
  // Set<id>  — present means user clicked "Run scripts".
  const _scriptsAllowed = new Set();

  let _disposeDeliveryWarning = null; // typed confirmation lifecycle; remove when panel migrates

  // What the panel is currently showing: 'doc' | 'library'.
  let _panelMode = "doc";

  // ── Inline SVG icons (24×24 viewBox, currentColor stroke/fill) ─────
  // No emojis anywhere in the panel chrome per design guideline.
  const ICON = {
    close:    '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M18 6 6 18M6 6l12 12"/></svg>',
    pinOff:   '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m12 17 .01 5"/><path d="M9 10v3.6a1 1 0 0 1-.4.8L6 16h12l-2.6-1.6a1 1 0 0 1-.4-.8V10"/><path d="M5 8h14l-1.7-3.4a1 1 0 0 0-.9-.6H7.6a1 1 0 0 0-.9.6Z"/></svg>',
    pinOn:    '<svg viewBox="0 0 24 24" width="16" height="16" fill="currentColor" stroke="currentColor" stroke-width="1.5" stroke-linejoin="round"><path d="M12 2.4 9.05 5.36a4 4 0 0 0-1.17 2.83v1.7L4 13.77l1.41 1.42 4.6-4.6V22h2v-11.4l4.59 4.59L18 13.78l-3.88-3.89v-1.7a4 4 0 0 0-1.17-2.83L10 2.4Z" fill-opacity=".18"/><path d="M12 22V12"/><path d="m9 6 3-3 3 3v3.2a3 3 0 0 0 .88 2.12L19 14H5l3.12-2.68A3 3 0 0 0 9 9.2V6Z"/></svg>',
    source:   '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="16 18 22 12 16 6"/><polyline points="8 6 2 12 8 18"/></svg>',
    copy:     '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="9" y="9" width="13" height="13" rx="2"/><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/></svg>',
    download: '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg>',
    print:    '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 6 2 18 2 18 9"/><path d="M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2"/><rect x="6" y="14" width="12" height="8" rx="1"/></svg>',
    library:  '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20"/><path d="M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2Z"/></svg>',
    docOpen:  '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="9" y1="13" x2="15" y2="13"/><line x1="9" y1="17" x2="15" y2="17"/></svg>',
    chevronDown: '<svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"/></svg>',
    arrowLeft: '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="19" y1="12" x2="5" y2="12"/><polyline points="12 19 5 12 12 5"/></svg>',
    warn:     '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M10.29 3.86 1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0Z"/><line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg>',
    search:   '<svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="11" cy="11" r="7"/><line x1="20" y1="20" x2="16.65" y2="16.65"/></svg>',
    // Format-specific icons used by chips and library rows.
    fmtMarkdown: '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8Z"/><polyline points="14 2 14 8 20 8"/><path d="M8 13h.01"/><path d="M8 17h.01"/><path d="M12 17v-4l1.6 2 1.4-2v4"/></svg>',
    fmtHtml:     '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="16 18 22 12 16 6"/><polyline points="8 6 2 12 8 18"/></svg>',
    fmtSvg:      '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8.5" cy="8.5" r="1.5"/><polyline points="21 15 16 10 5 21"/></svg>',
  };

  function _formatIcon(fmt) {
    if (fmt === "html") return ICON.fmtHtml;
    if (fmt === "svg")  return ICON.fmtSvg;
    return ICON.fmtMarkdown;  // markdown + unknown share doc icon
  }

  function _formatLabel(fmt) {
    if (fmt === "markdown") return "MD";
    if (fmt === "html")     return "HTML";
    if (fmt === "svg")      return "SVG";
    return (fmt || "DOC").toUpperCase();
  }

  // ── DOM helpers ─────────────────────────────────────────────────────

  function _ensurePanel() {
    let panel = document.getElementById("artifact-panel");
    if (panel) return panel;

    panel = document.createElement("aside");
    panel.id = "artifact-panel";
    panel.className = "artifact-panel artifact-panel-hidden";
    panel.setAttribute("aria-hidden", "true");
    panel.innerHTML =
      '<div class="artifact-panel-resize" data-art-resize title="Drag to resize"></div>' +
      '<header class="artifact-panel-header">' +
        '<div class="artifact-panel-titleblock">' +
          '<button class="artifact-iconbtn artifact-iconbtn-back" data-art-action="library" title="Open library" aria-label="Open library" data-art-mode-icon="doc">' +
            ICON.library +
          '</button>' +
          '<button class="artifact-iconbtn artifact-iconbtn-back" data-art-action="back-to-doc" title="Back to current artifact" aria-label="Back to current artifact" data-art-mode-icon="library" hidden>' +
            ICON.arrowLeft +
          '</button>' +
          '<div class="artifact-panel-titleinfo">' +
            '<div class="artifact-panel-titlerow">' +
              '<span class="artifact-format-pill" data-art-format></span>' +
              '<span class="artifact-panel-title" data-art-title></span>' +
            '</div>' +
            '<div class="artifact-panel-subtitle" data-art-subtitle hidden></div>' +
          '</div>' +
          '<select class="artifact-version-select" data-art-version hidden aria-label="Version"></select>' +
        '</div>' +
        '<div class="artifact-panel-actions" role="toolbar" aria-label="Artifact actions">' +
          '<button class="artifact-iconbtn" data-art-action="toggle-source" title="Toggle source view" aria-label="Toggle source view">' +
            ICON.source +
          '</button>' +
          '<button class="artifact-iconbtn" data-art-action="copy" title="Copy source" aria-label="Copy source">' +
            ICON.copy +
          '</button>' +
          '<button class="artifact-iconbtn" data-art-action="download" title="Download original" aria-label="Download">' +
            ICON.download +
          '</button>' +
          '<button class="artifact-iconbtn artifact-iconbtn-text" data-art-action="export-pdf" title="Export as PDF" aria-label="Export as PDF">PDF</button>' +
          '<button class="artifact-iconbtn" data-art-action="print" title="Print (Ctrl/Cmd+P)" aria-label="Print">' +
            ICON.print +
          '</button>' +
          '<span class="artifact-actions-sep" aria-hidden="true"></span>' +
          '<button class="artifact-iconbtn" data-art-action="pin" title="Pin" aria-label="Pin">' +
            ICON.pinOff +
          '</button>' +
          '<button class="artifact-iconbtn artifact-iconbtn-close" data-art-action="close" title="Close (Esc)" aria-label="Close">' +
            ICON.close +
          '</button>' +
        '</div>' +
      '</header>' +
      '<div class="artifact-panel-banner" data-art-banner hidden></div>' +
      '<div data-art-review-host hidden></div>' +
      '<div class="artifact-panel-body" data-art-body></div>';
    document.body.appendChild(panel);

    _restorePanelWidth(panel);
    panel.addEventListener("click", _onPanelClick);
    panel.addEventListener("change", _onPanelChange);
    panel.addEventListener("input", _onPanelInput);
    _wireResize(panel);
    return panel;
  }

  // ── Resizable panel (persisted to localStorage) ────────────────────
  const _PANEL_WIDTH_KEY = "tofu.artifactPanel.width";

  function _restorePanelWidth(panel) {
    try {
      const stored = parseInt(localStorage.getItem(_PANEL_WIDTH_KEY) || "", 10);
      if (Number.isFinite(stored) && stored >= 320 && stored <= window.innerWidth - 200) {
        panel.style.width = stored + "px";
      }
    } catch (e) { console.debug("[Artifacts] restore width failed:", e); }
  }

  function _wireResize(panel) {
    const handle = panel.querySelector("[data-art-resize]");
    if (!handle) return;
    let startX = 0, startW = 0;
    const onMove = (e) => {
      const dx = startX - e.clientX;
      const w = Math.max(320, Math.min(window.innerWidth - 200, startW + dx));
      panel.style.width = w + "px";
    };
    const onUp = () => {
      document.removeEventListener("mousemove", onMove);
      document.removeEventListener("mouseup", onUp);
      document.body.style.userSelect = "";
      try { localStorage.setItem(_PANEL_WIDTH_KEY, String(panel.offsetWidth)); }
      catch (e) { console.debug("[Artifacts] persist width failed:", e); }
    };
    handle.addEventListener("mousedown", (e) => {
      startX = e.clientX;
      startW = panel.offsetWidth;
      document.body.style.userSelect = "none";
      document.addEventListener("mousemove", onMove);
      document.addEventListener("mouseup", onUp);
      e.preventDefault();
    });
  }

  function _onPanelClick(e) {
    const libBtn = e.target.closest("[data-art-lib-id]");
    if (libBtn) {
      const id = libBtn.getAttribute("data-art-lib-id");
      if (id) open(id);
      return;
    }
    const pinChip = e.target.closest("[data-art-pin-id]");
    if (pinChip) {
      const id = pinChip.getAttribute("data-art-pin-id");
      e.stopPropagation();
      _togglePinById(id);
      return;
    }
    const richArtifact = e.target.closest('[data-conversation-action="open-artifact"]');
    if (richArtifact?.dataset.operation) { open(richArtifact.dataset.operation); return; }
    const btn = e.target.closest("[data-art-action]");
    if (!btn) return;
    const action = btn.getAttribute("data-art-action");
    if (action === "close") {
      closePanel();
    } else if (action === "library") {
      _showLibrary();
    } else if (action === "back-to-doc") {
      if (_activeId) open(_activeId);
    } else if (action === "copy") {
      _copySource();
    } else if (action === "download") {
      _download();
    } else if (action === "export-pdf") {
      _exportPdf();
    } else if (action === "print") {
      _print();
    } else if (action === "pin") {
      _togglePin();
    } else if (action === "toggle-source") {
      _toggleSourceView();
    } else if (action === "allow-scripts") {
      _allowScripts();
    }
  }

  function _onPanelChange(e) {
    const sel = e.target.closest("[data-art-version]");
    if (sel && sel.value && sel.value !== _activeId) {
      open(sel.value);
    }
  }

  function _onPanelInput(e) {
    const search = e.target.closest("[data-art-lib-search]");
    if (search) {
      _filterLibrary(search.value || "");
    }
  }

  // ── Open / close ────────────────────────────────────────────────────

  /**
   * Open an artifact in the right-side panel by id.  Fetches metadata +
   * raw content on demand; subsequent opens hit cache.
   */
  async function open(id) {
    if (!id) return;
    const panel = _ensurePanel();
    const openEpoch = ++_openEpoch;
    _activeId = id;
    _disposeReview?.(); _disposeReview = null;
    const reviewHost = panel.querySelector('[data-art-review-host]');
    if (reviewHost) reviewHost.hidden = true;

    _contentCache.clear();
    _scriptsAllowed.clear(); // consent belongs to this explicit preview session
    _panelMode = "doc";
    panel.dataset.mode = "doc";

    // Reveal the panel + adjust layout immediately so the user gets feedback.
    panel.classList.remove("artifact-panel-hidden");
    panel.setAttribute("aria-hidden", "false");
    document.body.classList.add("artifact-panel-open");

    const titleEl = panel.querySelector("[data-art-title]");
    const fmtEl   = panel.querySelector("[data-art-format]");
    const subEl   = panel.querySelector("[data-art-subtitle]");
    const bodyEl  = panel.querySelector("[data-art-body]");

    if (bodyEl) disposeRichResponse(bodyEl);

    _disposeDeliveryWarning?.(); _disposeDeliveryWarning = null;
    if (titleEl) titleEl.textContent = "Loading…";
    if (fmtEl) { fmtEl.textContent = ""; fmtEl.dataset.format = ""; }
    if (subEl) { subEl.hidden = true; subEl.textContent = ""; }
    if (bodyEl) bodyEl.innerHTML = '<div class="artifact-loading">' + ICON.docOpen + '<span>Loading artifact…</span></div>';

    try {
      const meta = await _ensureMeta(id);
      if (_activeId !== id || _openEpoch !== openEpoch) return;
      _renderHeader(panel, meta);
      if (reviewHost) {
        reviewHost.hidden = false;
        _disposeReview = mountArtifactReview(reviewHost, {
          load: signal => Api.artifacts.review(id, signal),
          save: (command, signal) => Api.artifacts.saveReview(id, command, signal),
          loadFacts: signal => Api.conversations.workingFacts(meta.conv_id, signal),
          text: (key, fallback) => typeof t === 'function' ? t(key) || fallback : fallback,
        });
      }

      const content = meta.format === "file" ? "" : await _ensureContent(id);
      if (_activeId !== id || _openEpoch !== openEpoch) return;
      _renderBody(panel, meta, content, /*sourceView=*/ false);
    } catch (err) {
      console.warn("[Artifacts] open failed:", err);

      if (_activeId !== id || _openEpoch !== openEpoch) return;
      if (bodyEl) {
        bodyEl.innerHTML =
          '<div class="artifact-error">' + ICON.warn +
          '<div><strong>Could not load artifact</strong>' +
          '<div class="artifact-error-detail">' +
          (typeof escapeHtml === "function" ? escapeHtml(String(err)) : String(err)) +
          '</div></div></div>';
      }
    }
  }

  function closePanel() {
    const panel = document.getElementById("artifact-panel");
    if (!panel) return;
    ++_openEpoch;
    _disposeReview?.(); _disposeReview = null;

    _disposeDeliveryWarning?.(); _disposeDeliveryWarning = null;
    const richBody = panel.querySelector('[data-art-body]');
    if (richBody) { disposeRichResponse(richBody); richBody.replaceChildren(); }
    panel.classList.add("artifact-panel-hidden");
    panel.setAttribute("aria-hidden", "true");
    document.body.classList.remove("artifact-panel-open");
    _contentCache.clear();
    _scriptsAllowed.clear();
    _activeId = null;
    _panelMode = "doc";
  }

  // ── Fetch helpers ───────────────────────────────────────────────────

  async function _ensureMeta(id) {
    // Visibility/cache is never authorization, including for legacy artifacts.
    const meta = await Api.artifacts.meta(id);
    if (!meta) throw new Error("artifact meta not found");
    _metaCache.set(id, meta);
    return meta;
  }

  async function _ensureContent(id) {
    if (_contentCache.has(id)) return _contentCache.get(id);
    const text = await Api.artifacts.contentText(id);
    if (_activeId === id) {
      _contentCache.clear(); // one active body, including multi-MiB prototypes
      _contentCache.set(id, text);
    }
    return text;
  }

  // ── Rendering ───────────────────────────────────────────────────────

  function _setMode(panel, mode) {
    panel.dataset.mode = mode;
    _panelMode = mode;
    if (mode === 'library') {
      ++_openEpoch;
      _disposeReview?.(); _disposeReview = null;
      const reviewHost = panel.querySelector('[data-art-review-host]');
      if (reviewHost) reviewHost.hidden = true;
    }
    // Toggle the leading icon (library button vs back-to-doc).
    panel.querySelectorAll('[data-art-mode-icon]').forEach(function (el) {
      const want = el.getAttribute("data-art-mode-icon");
      // Show "back-to-doc" only in library mode AND only if we have an
      // active doc to go back to.
      if (want === "library") {
        el.hidden = !(mode === "library" && _activeId);
      } else {
        el.hidden = (mode === "library");
      }
    });
    // Hide doc-specific actions in library mode (no doc to act on).
    const docOnly = ["toggle-source", "copy", "download", "export-pdf", "print", "pin"];
    panel.querySelectorAll(".artifact-panel-actions [data-art-action]").forEach(function (el) {
      const a = el.getAttribute("data-art-action");
      if (a === "close") return;
      el.hidden = (mode === "library") && docOnly.indexOf(a) !== -1;
    });
    panel.querySelectorAll(".artifact-actions-sep").forEach(function (el) {
      el.hidden = (mode === "library");
    });
  }

  function _renderHeader(panel, meta) {
    _setMode(panel, "doc");
    const titleEl = panel.querySelector("[data-art-title]");
    const fmtEl   = panel.querySelector("[data-art-format]");
    const subEl   = panel.querySelector("[data-art-subtitle]");
    const titleStr = meta.title || ("artifact-" + (meta.id || "").slice(0, 8));
    if (titleEl) titleEl.textContent = titleStr;
    if (fmtEl) {
      fmtEl.textContent = _formatLabel(meta.format);
      fmtEl.dataset.format = meta.format || "";
    }
    if (subEl) {
      const parts = [];
      if (meta.size_bytes) parts.push(_formatBytes(meta.size_bytes));
      if (meta.created_at) parts.push(_relativeTime(meta.created_at));
      if ((meta.version || 1) > 1) parts.push("v" + meta.version);
      if (parts.length) {
        subEl.hidden = false;
        subEl.textContent = parts.join(" · ");
      } else {
        subEl.hidden = true;
        subEl.textContent = "";
      }
    }
    for (const action of ["toggle-source", "copy", "print", "export-pdf"]) {
      const control = panel.querySelector('[data-art-action="' + action + '"]');
      if (control) control.hidden = meta.format === "file";
    }
    const pinBtn = panel.querySelector('[data-art-action="pin"]');
    if (pinBtn) {
      pinBtn.innerHTML = meta.pinned ? ICON.pinOn : ICON.pinOff;
      pinBtn.classList.toggle("artifact-iconbtn-active", !!meta.pinned);
      pinBtn.setAttribute("aria-pressed", meta.pinned ? "true" : "false");
    }
    _populateVersionSelect(panel, meta).catch(function (e) {
      console.debug("[Artifacts] version select populate failed:", e);
    });
  }

  async function _populateVersionSelect(panel, meta) {
    const sel = panel.querySelector("[data-art-version]");
    if (!sel) return;
    const openEpoch = _openEpoch;
    try {
      const payload = await Api.artifacts.versions(meta.id);
      if (_activeId !== meta.id || _openEpoch !== openEpoch) return;
      if (!payload) throw new Error("versions fetch failed");
      const chain = (payload && payload.versions) || [];
      if (chain.length <= 1) {
        sel.hidden = true;
        sel.innerHTML = "";
        return;
      }
      sel.innerHTML = chain.map(function (v) {
        const sel_attr = v.id === meta.id ? " selected" : "";
        return '<option value="' + v.id + '"' + sel_attr + '>' +
          'v' + (v.version || 1) +
          '</option>';
      }).join("");
      sel.hidden = false;
    } catch (e) {
      console.debug("[Artifacts] versions fetch failed:", e);
      sel.hidden = true;
      sel.innerHTML = "";
    }
  }

  function _renderBody(panel, meta, content, sourceView) {

    _disposeDeliveryWarning?.(); _disposeDeliveryWarning = null;
    const bodyEl = panel.querySelector("[data-art-body]");
    const banner = panel.querySelector("[data-art-banner]");
    if (!bodyEl) return;

    disposeRichResponse(bodyEl);
    bodyEl.classList.remove('rich-response');
    // Reset state from previous artifact

    if (banner) {
      banner.hidden = true;
      banner.innerHTML = "";
    }
    bodyEl.innerHTML = "";
    bodyEl.dataset.sourceView = sourceView ? "1" : "0";

    if (sourceView) {
      const pre = document.createElement("pre");
      pre.className = "artifact-source-view";
      pre.textContent = content;
      bodyEl.appendChild(pre);
      return;
    }

    const fmt = meta.format;
    if (fmt === "file") {
      renderPublishedFile(bodyEl, meta.meta?.responseFile, {
        text: (key, fallback) => t(key) || fallback,
        download: _download,
      });
    } else if (fmt === "rich") {
      renderRichResponse(bodyEl, meta.contentJSON || content, { conversationId: meta.conv_id, text: (key, fallback) => t(key) || fallback });
    } else if (fmt === "markdown") {
      _renderMarkdown(bodyEl, content);
    } else if (fmt === "html") {
      _renderHtml(panel, banner, bodyEl, meta, content);
    } else if (fmt === "svg") {
      _renderSvg(panel, banner, bodyEl, meta, content);
    } else {
      const pre = document.createElement("pre");
      pre.className = "artifact-source-view";
      pre.textContent = content;
      bodyEl.appendChild(pre);
    }
  }

  function _renderMarkdown(bodyEl, content) {
    // renderMarkdown (core.js:2906) already runs DOMPurify.sanitize on the
    // marked.parse output, so it's safe to inject as HTML.
    let html;
    try {
      html = (typeof renderMarkdown === "function")
        ? renderMarkdown(content)
        : (typeof escapeHtml === "function" ? "<pre>" + escapeHtml(content) + "</pre>"
                                            : "<pre>" + content + "</pre>");
    } catch (e) {
      console.warn("[Artifacts] renderMarkdown failed, falling back to escapeHtml:", e);
      html = (typeof escapeHtml === "function" ? "<pre>" + escapeHtml(content) + "</pre>"
                                                : "<pre>" + content + "</pre>");
    }
    const wrap = document.createElement("article");
    wrap.className = "artifact-md md-content";
    wrap.innerHTML = html;
    bodyEl.appendChild(wrap);
  }

  function _renderHtml(panel, banner, bodyEl, meta, content) {
    const allowScripts = _scriptsAllowed.has(meta.id);
    const hasScripts = ["html", "svg"].includes(meta.format) || meta.meta?.responseFile?.scriptRisk || /<script[\s>]|\son\w+\s*=|javascript:/i.test(content);

    if (hasScripts && banner) {
      banner.hidden = false;
      _disposeDeliveryWarning = renderScriptWarning(banner,
        () => { if (_activeId === meta.id) _allowScripts(); },
        (key, fallback) => t(key) || fallback, {
        scriptsAllowed: allowScripts,
        interactiveDownload: () => _download(true, meta.id),
      });
    }

    const iframe = document.createElement("iframe");
    iframe.className = "artifact-iframe";

    iframe.title = meta.title || "Artifact preview";
    iframe.setAttribute("referrerpolicy", "no-referrer");
    iframe.setAttribute("loading", "lazy");
    // ── /view (default) vs /raw + srcdoc (opt-in) ──────────────────
    // Default path uses ``/api/artifacts/<id>/view`` which:
    //   • Wraps the artifact in a minimal HTML shell that injects our
    //     trusted KaTeX bundle so $..$ / $$..$$ / \(..\) / \[..\] in
    //     the model HTML render as proper math even when the model's
    //     own <script> tags are blocked.
    //   • Ships ``Content-Security-Policy: sandbox allow-scripts;
    //     default-src 'self'; script-src 'self'; …`` so ONLY our
    //     same-origin KaTeX scripts run.  Inline + remote model
    //     <script> blocks are forbidden by ``script-src 'self'``;
    //     inline ``on*=`` handlers and ``javascript:`` href are too.
    //   • The iframe sandbox ``allow-scripts`` (NO allow-same-origin)
    //     is the second layer — even if a script slipped through, the
    //     iframe is an opaque origin and can't reach parent
    //     localStorage / cookies / DOM.
    //   • Has a real document URL, so <a href="#anchor"> resolves to
    //     a same-document fragment scroll (TOC works), and relative
    //     URLs stay scoped to /api/artifacts/* — see memory
    //     ``artifacts-iframe-srcdoc-anchor-trap``.
    //
    // The user-opt-in allow-scripts path keeps using srcdoc + /raw
    // because the more permissive /view CSP still blocks model
    // scripts; opt-in needs the broader sandbox model.
    if (allowScripts) {
      iframe.setAttribute("sandbox", "allow-scripts");
      iframe.srcdoc = content;
    } else {
      iframe.setAttribute("sandbox", "allow-scripts");
      iframe.src = Api.artifacts.viewUrl(meta.id);
    }
    bodyEl.appendChild(iframe);
  }

  function _renderSvg(panel, banner, bodyEl, meta, content) {
    const hasScripts = ["html", "svg"].includes(meta.format) || meta.meta?.responseFile?.scriptRisk || /<script[\s>]|\son\w+\s*=|javascript:/i.test(content);
    if (hasScripts) {
      // Reuse the HTML iframe path so the script-block consent flow
      // (and the trusted-KaTeX wrapper) handle the dynamic case.
      _renderHtml(panel, banner, bodyEl, meta, content);
      return;
    }
    // Static SVG — render as an <img> via data: URL (sandboxed by browser).
    const wrap = document.createElement("div");
    wrap.className = "artifact-svg";
    const img = document.createElement("img");
    img.alt = meta.title || "SVG artifact";
    img.src = "data:image/svg+xml;utf8," + encodeURIComponent(content);
    wrap.appendChild(img);
    bodyEl.appendChild(wrap);
  }

  // ── Header actions ──────────────────────────────────────────────────

  async function _copySource() {
    if (!_activeId) return;
    try {
      const text = await _ensureContent(_activeId);
      await _safeClipboardWrite(text);
      if (typeof showToast === "function") {
        showToast("", "Copied", "Source copied to clipboard.", 1800);
      }
    } catch (e) {
      console.warn("[Artifacts] copy failed:", e);
    }
  }

  async function _download(interactive = false, id = _activeId) {
    if (!id || id !== _activeId) return;
    try {
      const meta = await _ensureMeta(id);
      if (_activeId !== id) return; // a switched/closed panel cannot reuse consent
      const link = document.createElement("a");
      link.href = Api.artifacts.downloadUrl(id) + (interactive === true ? "?interactive=1" : "");
      link.rel = "noopener noreferrer";
      // Every source follows the server's live owner/deleted checks and safe
      // attachment MIME/filename policy; never download a warm cached Blob.
      document.body.append(link); link.click(); link.remove();
    } catch (e) {
      console.warn("[Artifacts] download failed:", e);
    }
  }

  async function _togglePin() {
    if (!_activeId) return;
    try {
      const meta = await _ensureMeta(_activeId);
      await _setPinned(_activeId, !meta.pinned);
    } catch (e) {
      console.warn("[Artifacts] pin failed:", e);
    }
  }

  async function _togglePinById(id) {
    if (!id) return;
    try {
      const meta = await _ensureMeta(id);
      const updated = await _setPinned(id, !meta.pinned);
      // Re-render the library row in place if visible.
      const panel = document.getElementById("artifact-panel");
      if (panel && _panelMode === "library") {
        const row = panel.querySelector('[data-art-lib-id="' + CSS.escape(id) + '"]');
        if (row) {
          const pinBtn = row.querySelector('[data-art-pin-id]');
          if (pinBtn) {
            pinBtn.innerHTML = updated.pinned ? ICON.pinOn : ICON.pinOff;
            pinBtn.classList.toggle("is-pinned", !!updated.pinned);
            pinBtn.setAttribute("aria-pressed", updated.pinned ? "true" : "false");
          }
        }
      }
    } catch (e) {
      console.warn("[Artifacts] pin failed:", e);
    }
  }

  async function _setPinned(id, pinned) {
    const updated = await Api.artifacts.pin(id, pinned);
    if (!updated) throw new Error("pin failed");
    _metaCache.set(id, updated);
    if (id === _activeId) {
      const panel = document.getElementById("artifact-panel");
      if (panel) _renderHeader(panel, updated);
    }
    return updated;
  }

  async function _toggleSourceView() {
    if (!_activeId) return;
    const panel = document.getElementById("artifact-panel");
    if (!panel) return;
    const bodyEl = panel.querySelector("[data-art-body]");
    const cur = (bodyEl && bodyEl.dataset.sourceView === "1");
    const meta = await _ensureMeta(_activeId);
    const content = await _ensureContent(_activeId);
    _renderBody(panel, meta, content, /*sourceView=*/ !cur);
    const srcBtn = panel.querySelector('[data-art-action="toggle-source"]');
    if (srcBtn) srcBtn.classList.toggle("artifact-iconbtn-active", !cur);
  }

  async function _exportPdf() {
    if (!_activeId) return;
    try {
      // Trigger a download via an anchor — preserves the server-supplied
      // Content-Disposition filename and avoids buffering the PDF in JS.
      const a = document.createElement("a");
      a.href = Api.artifacts.exportPdfUrl(_activeId);
      a.target = "_blank";
      a.rel = "noopener";
      a.style.display = "none";
      document.body.appendChild(a);
      a.click();
      a.remove();
      if (typeof showToast === "function") {
        showToast("", "Export started", "Generating PDF…", 2200);
      }
    } catch (e) {
      console.warn("[Artifacts] export PDF failed:", e);
    }
  }

  function _print() {
    const panel = document.getElementById("artifact-panel");
    if (!panel) return;
    const iframe = panel.querySelector("iframe.artifact-iframe");
    if (iframe && iframe.contentWindow) {
      try {
        iframe.contentWindow.focus();
        iframe.contentWindow.print();
        return;
      } catch (e) {
        console.debug("[Artifacts] iframe print failed, falling back:", e);
      }
    }
    // Markdown / SVG: print via PDF download (server renders it).
    _exportPdf();
  }

  // ── Library ─────────────────────────────────────────────────────────

  async function _showLibrary() {
    const panel = _ensurePanel();

    _disposeDeliveryWarning?.(); _disposeDeliveryWarning = null;
    _contentCache.clear(); _scriptsAllowed.clear();
    _activeId = null;
    panel.classList.remove("artifact-panel-hidden");
    panel.setAttribute("aria-hidden", "false");
    document.body.classList.add("artifact-panel-open");
    _setMode(panel, "library");

    const titleEl   = panel.querySelector("[data-art-title]");
    const fmtEl     = panel.querySelector("[data-art-format]");
    const subEl     = panel.querySelector("[data-art-subtitle]");
    const bodyEl    = panel.querySelector("[data-art-body]");
    const banner    = panel.querySelector("[data-art-banner]");
    const versionSel= panel.querySelector("[data-art-version]");
    if (titleEl) titleEl.textContent = "Library";
    if (fmtEl) { fmtEl.textContent = ""; fmtEl.dataset.format = ""; }
    if (subEl) { subEl.hidden = true; subEl.textContent = ""; }
    if (banner) { banner.hidden = true; banner.innerHTML = ""; }
    if (versionSel) { versionSel.hidden = true; versionSel.innerHTML = ""; }

    if (bodyEl) bodyEl.innerHTML = '<div class="artifact-loading">' + ICON.library + '<span>Loading library…</span></div>';
    try {
      const payload = await Api.artifacts.library(120);
      if (!payload) throw new Error("library load failed");
      _renderLibrary(bodyEl, (payload && payload.artifacts) || []);
    } catch (e) {
      console.warn("[Artifacts] library load failed:", e);
      if (bodyEl) bodyEl.innerHTML =
        '<div class="artifact-error">' + ICON.warn +
        '<div><strong>Failed to load library.</strong>' +
        '<div class="artifact-error-detail">' +
        (typeof escapeHtml === "function" ? escapeHtml(String(e)) : String(e)) +
        '</div></div></div>';
    }
  }

  function _renderLibrary(bodyEl, items) {
    if (!bodyEl) return;
    if (!items.length) {
      bodyEl.innerHTML =
        '<div class="artifact-empty">' +
          '<div class="artifact-empty-icon">' + ICON.library + '</div>' +
          '<div class="artifact-empty-title">No artifacts yet</div>' +
          '<div class="artifact-empty-text">Saved reports, generated HTML, and pinned outputs show up here.</div>' +
        '</div>';
      return;
    }
    const _esc = (typeof escapeHtml === "function") ? escapeHtml : function (s) { return String(s); };
    const rows = items.map(function (a) {
      const id = _esc(a.id || "");
      const title = _esc(a.title || ("artifact-" + (a.id || "").slice(0, 8)));
      const fmtLabel = _formatLabel(a.format);
      const fmtClass = "artifact-format-pill artifact-format-" + (a.format || "doc");
      const ts = a.created_at ? _relativeTime(a.created_at) : "";
      const sz = a.size_bytes ? _formatBytes(a.size_bytes) : "";
      const meta = [fmtLabel, sz, ts].filter(Boolean).map(_esc).join(" · ");
      const pinClass = a.pinned ? "is-pinned" : "";
      const pinIcon = a.pinned ? ICON.pinOn : ICON.pinOff;
      return (
        '<button class="artifact-lib-row" data-art-lib-id="' + id + '" data-art-search="' + (title + " " + meta).toLowerCase().replace(/"/g, "&quot;") + '">' +
          '<span class="artifact-lib-icon">' + _formatIcon(a.format) + '</span>' +
          '<span class="artifact-lib-main">' +
            '<span class="artifact-lib-title">' + title + '</span>' +
            '<span class="artifact-lib-meta">' +
              '<span class="' + fmtClass + '">' + fmtLabel + '</span>' +
              (sz ? '<span class="artifact-lib-dim">' + _esc(sz) + '</span>' : '') +
              (ts ? '<span class="artifact-lib-dim">' + _esc(ts) + '</span>' : '') +
            '</span>' +
          '</span>' +
          '<span class="artifact-lib-pin ' + pinClass + '" data-art-pin-id="' + id + '" role="button" tabindex="-1" title="' + (a.pinned ? "Unpin" : "Pin") + '" aria-pressed="' + (a.pinned ? "true" : "false") + '">' + pinIcon + '</span>' +
        '</button>'
      );
    }).join("");
    bodyEl.innerHTML =
      '<div class="artifact-lib">' +
        '<div class="artifact-lib-search">' +
          '<span class="artifact-lib-search-icon">' + ICON.search + '</span>' +
          '<input type="search" placeholder="Filter artifacts…" data-art-lib-search aria-label="Filter artifacts">' +
        '</div>' +
        '<div class="artifact-lib-list">' + rows + '</div>' +
      '</div>';
  }

  function _filterLibrary(query) {
    const panel = document.getElementById("artifact-panel");
    if (!panel) return;
    const q = (query || "").trim().toLowerCase();
    const rows = panel.querySelectorAll(".artifact-lib-row");
    let visible = 0;
    rows.forEach(function (r) {
      const hay = r.getAttribute("data-art-search") || "";
      const match = !q || hay.indexOf(q) !== -1;
      r.style.display = match ? "" : "none";
      if (match) visible++;
    });
    /* When a filter matches nothing, every row is display:none — show an
     * explicit "no matches" line so the list doesn't look blank/broken
     * (sibling of the conv-list collapse bug: never leave a control with
     * zero visible items and no fallback). */
    const listEl = panel.querySelector(".artifact-lib-list");
    if (!listEl) return;
    let noResult = listEl.querySelector(".artifact-lib-noresult");
    if (visible === 0 && rows.length > 0) {
      if (!noResult) {
        noResult = document.createElement("div");
        noResult.className = "artifact-lib-noresult";
        listEl.appendChild(noResult);
      }
      const _esc = (typeof escapeHtml === "function") ? escapeHtml : function (s) { return String(s); };
      noResult.textContent = "No artifacts match \u201c" + _esc(q) + "\u201d";
      noResult.style.display = "";
    } else if (noResult) {
      noResult.style.display = "none";
    }
  }

  async function _allowScripts() {
    const id = _activeId;
    if (!id) return;
    try {
      const meta = await _ensureMeta(id);
      const content = await _ensureContent(id);
      if (_activeId !== id) return;
      _scriptsAllowed.add(id);
      _renderBody(_ensurePanel(), meta, content, false);
    } catch (error) {
      console.warn("[Artifacts] consent failed:", error);
      return;
    }
    // Audit: best-effort, fire and forget.
    try {
      Api.clientError.report({
        message: "[debugLog][info] artifact_scripts_allowed id=" + _activeId,
        url: location.href,
        extra: { artifactId: _activeId },
      });
    } catch (e) {
      console.debug("[Artifacts] consent log build failed:", e);
    }

  }

  // ── Formatting helpers ─────────────────────────────────────────────

  function _formatBytes(n) {
    if (!Number.isFinite(n) || n <= 0) return "";
    if (n < 1024) return n + " B";
    if (n < 1024 * 1024) return Math.round(n / 1024) + " KB";
    return (n / (1024 * 1024)).toFixed(1) + " MB";
  }

  function _relativeTime(epochMs) {
    if (!Number.isFinite(epochMs) || epochMs <= 0) return "";
    const diff = Date.now() - epochMs;
    if (diff < 0) return "just now";
    const sec = Math.round(diff / 1000);
    if (sec < 30)   return "just now";
    if (sec < 60)   return sec + "s ago";
    const min = Math.round(sec / 60);
    if (min < 60)   return min + "m ago";
    const hr  = Math.round(min / 60);
    if (hr  < 24)   return hr + "h ago";
    const day = Math.round(hr / 24);
    if (day < 7)    return day + "d ago";
    const wk  = Math.round(day / 7);
    if (wk  < 5)    return wk + "w ago";
    try {
      return new Date(epochMs).toLocaleDateString();
    } catch (_) {
      return "";
    }
  }

  // ── Hydration: join artifact metadata to stable Turn identity ──────

  function _artifactTurnId(conv, meta) {
    const state = runtimeScope.ConversationTurnRead?.state?.(conv);
    if (!state) return '';
    const directId = String(meta?.turn_id || meta?.msg_id || '');
    if (directId && state.turnsById?.[directId]) return directId;
    const taskId = String(meta?.task_id || '');
    if (taskId) {
      const attempt = Object.values(state.attemptsById || {}).find(
        (candidate) => candidate && candidate.taskId === taskId,
      );
      if (attempt?.turnId && state.turnsById[attempt.turnId]) return attempt.turnId;
    }
    return runtimeScope.ConversationTurnRead?.latest?.(
      conv,
      (turn) => turn.actor === 'assistant' || turn.actor === 'planner',
    )?.turnId || '';
  }

  function _artifactPresentation(meta) {
    const id = String(meta?.id || '');
    if (!id) return null;
    const sourcePath = typeof meta?.source_ref?.path === 'string'
      ? meta.source_ref.path : '';
    const sizeBytes = Number(meta?.size_bytes);
    const version = Number(meta?.version);
    const createdAt = Number(meta?.created_at);
    return Object.freeze({
      id,
      format: String(meta?.format || 'doc'),
      title: String(meta?.title || `artifact-${id.slice(0, 8)}`),
      ...(Number.isFinite(sizeBytes) && sizeBytes > 0 ? { sizeBytes } : {}),
      ...(sourcePath ? { sourcePath } : {}),
      ...(Number.isFinite(version) ? { version } : {}),
      ...(Number.isFinite(createdAt) ? { createdAt } : {}),
    });
  }

  /** Replace the active conversation's bounded artifact read model. */
  async function hydrateConversation(conv, hasArtifacts) {
    if (!conv || !conv.id) return;
    const epoch = (_hydrateEpoch.get(conv) || 0) + 1;
    _hydrateEpoch.set(conv, epoch);
    _artifactHints.set(conv, hasArtifacts);
    if (!runtimeScope.ConversationSurfacePresentation?.ownsConversation?.(conv.id)) return;
    if (hasArtifacts === false) {
      runtimeScope.ConversationSurfacePresentation?.setArtifacts?.(
        conv.id, new Map(),
      );
      return;
    }
    try {
      const payload = await Api.artifacts.forConv(conv.id);
      if (_hydrateEpoch.get(conv) !== epoch) return;
      const rows = Array.isArray(payload?.artifacts) ? payload.artifacts : [];
      const byTurn = new Map();
      for (const meta of rows) {
        if (!meta?.id) continue;
        _metaCache.set(meta.id, meta);
        const turnId = _artifactTurnId(conv, meta);
        const artifact = _artifactPresentation(meta);
        if (!turnId || !artifact) continue;
        const existing = byTurn.get(turnId) || [];
        const duplicateIndex = existing.findIndex((item) => item.id === artifact.id);
        if (duplicateIndex >= 0) existing[duplicateIndex] = artifact;
        else existing.push(artifact);
        byTurn.set(turnId, existing);
      }
      for (const [turnId, artifacts] of byTurn) {
        byTurn.set(turnId, Object.freeze([...artifacts]));
      }
      runtimeScope.ConversationSurfacePresentation?.setArtifacts?.(conv.id, byTurn);
    } catch (e) {
      console.debug("[Artifacts] hydrateConversation failed:", e);
    }
  }

  // ── Keyboard: Esc closes the panel; Ctrl/Cmd+P prints when panel open
  document.addEventListener("keydown", function (e) {

    if (document.querySelector('dialog[open]')) return; // native modal owns Escape/focus
    if (e.key === "Escape" && _activeId) {
      closePanel();
      return;
    }
    // Print only when the panel is open AND focus isn't in a text input
    if ((e.ctrlKey || e.metaKey) && (e.key === "p" || e.key === "P")) {
      const panel = document.getElementById("artifact-panel");
      if (panel && !panel.classList.contains("artifact-panel-hidden")) {
        const tag = (e.target && e.target.tagName) || "";
        if (tag !== "INPUT" && tag !== "TEXTAREA" && _metaCache.get(_activeId)?.format !== "file") {
          e.preventDefault();
          _print();
        }
      }
    }
  });

  // ── Public façade ──────────────────────────────────────────────────
  runtimeScope.Artifacts = {
    open: open,
    closePanel: closePanel,
    showLibrary: _showLibrary,
    hydrateConversation: hydrateConversation,
    activateConversation: conv => {
      if (_artifactHints.has(conv)) void hydrateConversation(conv, _artifactHints.get(conv));
    },
    // Exposed for tests / debug
    _meta: _metaCache,
    _content: _contentCache,
    _filterLibrary: _filterLibrary,
  };
})();
/* ===== migrated source: ui/conversation_list.js ===== */
/* ═══════════════════════════════════════════════════════════════════
   conversation list — extracted from ui.js (split 2026-05-28)

   Conversation list rendering — sidebar conv list, folder tabs, search.

   This file is concatenated by Vite's module graph — symbols share
   the same window scope as every other frontend/src/runtime/*.js file. No
   exports / imports needed.
   ═══════════════════════════════════════════════════════════════════ */

function formatConvTime(ts) {
  const labels = conversationTimestampLabels(
    ts, Date.now(), document.documentElement.lang,
    t('sidebar.dateToday'), t('sidebar.dateYesterday'),
  );
  if (!labels) return '';
  return `<span class="conv-date-text">${escapeHtml(labels.date)}</span><span class="conv-date-sep">·</span><span class="conv-date-time">${labels.time}</span>`;
}

/* ── Date grouping for the conversation list ──
 * Rows are sorted recency-first (_convSorter), so each date bucket is a
 * contiguous run. Each bucket gets a clickable header that folds its rows.
 * The ">30 days" ("older") bucket starts collapsed. */
const _CONV_OLDER_DAYS = 30;
/** Set of date-group keys currently collapsed. "older" starts collapsed by
 *  default; every other key only lands here via an explicit user toggle. */
const _collapsedConvGroups = new Set(['older']);
/** Keys the user has EXPLICITLY toggled this session. A user's choice always
 *  wins over the force-expand guards below (which exist only to stop the
 *  default-collapsed "older" bucket from hiding the whole list on load). */
const _userToggledConvGroups = new Set();

/** Classify a timestamp into a date-group key. */
/* Canonical date-group order for the sidebar sections. Sorting group-FIRST
 * keeps every date bucket a single contiguous run — the invariant the
 * grouped renderer relies on when emitting section headers. Floating active
 * conversations across group boundaries interleaved the sections into
 * 今天→昨天→今天 (duplicate headers). */
const _CONV_GROUP_RANK = { today: 0, yesterday: 1, prev7: 2, prev30: 3, older: 4 };

function _convGroupRank(c) {
  const r = _CONV_GROUP_RANK[_convDateGroupKey(c.updatedAt || c.createdAt)];
  return r === undefined ? _CONV_GROUP_RANK.older : r;
}

function _convDateGroupKey(ts) {
  if (!ts) return 'older';
  const now = new Date();
  const startToday = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();
  const dayMs = 86400000;
  if (ts >= startToday) return 'today';
  if (ts >= startToday - dayMs) return 'yesterday';
  if (ts >= startToday - 6 * dayMs) return 'prev7';
  if (ts >= startToday - (_CONV_OLDER_DAYS - 1) * dayMs) return 'prev30';
  return 'older';
}

const _CONV_GROUP_I18N = {
  today: 'sidebar.dateToday',
  yesterday: 'sidebar.dateYesterday',
  prev7: 'sidebar.datePrev7',
  prev30: 'sidebar.datePrev30',
  older: 'sidebar.dateOlder',
};

/** Collapsible section-header markup for a date-group key + its row count. */
function _convGroupHeaderHtml(key, count, collapsed) {
  const label = t(_CONV_GROUP_I18N[key] || key);
  const chevron = `<svg class="conv-date-chevron" width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"/></svg>`;
  return `<button type="button" class="conv-date-group${collapsed ? ' collapsed' : ''}" data-group="${key}" data-tofu-action="_toggleConvGroup('${key}')">` +
    `${chevron}<span class="conv-date-label">${label}</span><span class="conv-date-count">${count}</span></button>`;
}

/** Toggle a date group's collapsed state and re-render. */
function _toggleConvGroup(key) {
  _userToggledConvGroups.add(key);
  if (_collapsedConvGroups.has(key)) _collapsedConvGroups.delete(key);
  else _collapsedConvGroups.add(key);
  _lastConvListHash = "";          // force a full rebuild past the hash guard
  renderConversationList();
}

let _lastConvListHash = "";
let _lastConvStructHash = "";        // struct part of the split hash (row identity/order/title/date/folder)
let _lastRenderedSearchQuery = "";   // guard: skip background re-renders in search mode

/* PERF: Fast-path for conversation switch — instead of rebuilding the
 * entire sidebar from scratch (O(N) HTML generation + innerHTML assignment),
 * just move the .active class between two DOM elements (O(1)).
 * Returns true if the fast-path was sufficient, false if a full rebuild is needed. */
let _lastActiveConvId = null;
function _swapActiveConvItem(newActiveId) {
  if (sidebarSearchQuery) return false; // search mode — need full rebuild
  const oldId = _lastActiveConvId;
  /* No-op only if the DOM already reflects the active state. A prior
   * hash-skipped render can leave _lastActiveConvId pointing at a conv
   * whose .active class was never applied (or applied to the wrong row),
   * which is what makes the active indicator dot + status tag silently
   * disappear. Verify the target row actually carries .active before
   * trusting the cache; otherwise fall through and re-apply it. */
  if (oldId === newActiveId) {
    if (!newActiveId) return true;
    const cur = document.querySelector(`.conv-item[data-conv-id="${CSS.escape(newActiveId)}"]`);
    if (cur && cur.classList.contains('active')) return true;
    if (!cur) return false; // not in DOM yet — need full rebuild
    document.querySelectorAll('.conv-item.active').forEach(el => {
      if (el !== cur) el.classList.remove('active');
    });
    cur.classList.add('active');
    _lastConvListHash = "";
    return true;
  }
  /* Locate the new row FIRST — if it isn't in the DOM yet we must NOT
   * mutate any state (neither _lastActiveConvId nor the old row's class),
   * otherwise the subsequent renderConversationList() can early-return on
   * a stale hash and leave the sidebar with no active row at all. */
  if (newActiveId) {
    const newEl = document.querySelector(`.conv-item[data-conv-id="${CSS.escape(newActiveId)}"]`);
    if (!newEl) {
      /* New conv not in DOM yet — need a full rebuild. Force the hash to
       * miss so the caller's renderConversationList() actually repaints. */
      _lastConvListHash = "";
      return false;
    }
    /* Clear .active from every currently-active row (defensive: there
     * should be exactly one, but a desynced cache may have left several),
     * then activate the target. */
    document.querySelectorAll('.conv-item.active').forEach(el => {
      if (el !== newEl) el.classList.remove('active');
    });
    newEl.classList.add('active');
  } else if (oldId) {
    const oldEl = document.querySelector(`.conv-item[data-conv-id="${CSS.escape(oldId)}"]`);
    if (oldEl) oldEl.classList.remove('active');
  }
  _lastActiveConvId = newActiveId;
  /* Invalidate the hash so a subsequent full renderConversationList()
   * won't skip due to stale hash (the hash includes active state). */
  _lastConvListHash = "";
  return true;
}

/* ── Folder tab bar ── */
let _lastFolderTabsHash = '';
let _lastFolderTabsContentHash = '';
let _lastFolderTabsStructHash = '';

/* i18n race fix: the locale chunk is a dynamic import that lands AFTER the
 * IndexedDB cache-first sidebar paint (hydrateConversationCatalogFromCache) on any cold
 * load — guaranteed on a cache-bypassing force refresh, where it queues
 * behind the multi-MB app chunk. Every t() read in that first paint therefore
 * renders the RAW KEY (sidebar.dateToday / sidebar.uncategorized / …), and
 * the hash guards above would skip every later repaint because the
 * conversation DATA never changed — leaving the keys stuck on screen.
 * _applyI18n() can't help either: this list is JS-built innerHTML without
 * data-i18n attributes. i18n ready() and every live language switch dispatch
 * `tofu:language-change` (same pattern as the pet / skills / settings /
 * memory panels), so invalidate ALL sidebar render guards and force one full
 * repaint once a real translation table exists. */
window.addEventListener('tofu:language-change', function () {
  if (!document.getElementById('convList')) return;
  _lastConvListHash = '';
  _lastConvStructHash = '';
  _lastRenderedSearchQuery = '';   // search-mode guard: force a rebuild too
  _lastFolderTabsHash = '';
  _lastFolderTabsContentHash = '';
  _lastFolderTabsStructHash = '';
  if (typeof renderConversationList === 'function') renderConversationList();
  if (typeof paperMode === 'undefined' || !paperMode) {
    const active = conversations.find(item => item.id === activeConvId);
    const topbar = document.getElementById('topbarTitle');
    if (topbar && active?.title === 'New Chat') {
      topbar.textContent = _conversationDisplayTitle(
        active.title, t('chat.newConversation'));
    } else if (topbar && !activeConvId
        && !topbar.querySelector('.topbar-folder-badge')) {
      topbar.textContent = _conversationDisplayTitle(
        'New Chat', t('chat.newConversation'));
    }
  }
});

/* Vertical project-rail collapsed/expanded state (icon-only ⇄ labeled),
 * persisted like the old expand state. Kept in localStorage so the choice
 * survives reloads and spans conversations. The toggle handler in
 * main_folders_mobile.js writes the SAME key. */
const RAIL_COLLAPSE_KEY = 'tofu_project_rail_collapsed';
const RAIL_HAS_FOLDERS_KEY = 'tofu_has_folders';
function _readRailCollapsed() {
  try { return localStorage.getItem(RAIL_COLLAPSE_KEY) === '1'; }
  catch (_e) { return false; }
}
/* Persist the "does this user have ≥1 folder" hint + keep the pre-paint
 * html[data-rail] attribute in sync. The inline script in index.html reads the
 * localStorage hint on the NEXT load to settle the sidebar width BEFORE first
 * paint (zero CLS). Syncing the attribute here also keeps THIS session correct
 * if the rail appears/disappears after load (first folder created, or the
 * zero-folder correction after a fresh install). */
function _persistRailHint(hasRail) {
  try {
    if (hasRail) localStorage.setItem(RAIL_HAS_FOLDERS_KEY, '1');
    else localStorage.removeItem(RAIL_HAS_FOLDERS_KEY);
  } catch (_e) { /* private-mode / disabled storage — hint is best-effort */ }
  try {
    const root = document.documentElement;
    if (hasRail) root.setAttribute('data-rail', _readRailCollapsed() ? 'collapsed' : 'full');
    else root.removeAttribute('data-rail');
  } catch (_e) { /* no document root — non-DOM context */ }
}



function renderFolderTabs(folders, activeFolderId, allConvs) {
  const tabsEl = document.getElementById('folderTabs');
  if (!tabsEl) return;
  try {
    _renderFolderTabsInner(tabsEl, folders, activeFolderId, allConvs);
  } catch (e) {
    console.error('[renderFolderTabs] Error:', e);
    // On error, ensure the rail isn't left in a broken state — minimal fallback.
    try { tabsEl.innerHTML = '<div class="project-rail-list"><button class="folder-tab folder-tab-add" title="New folder"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg></button></div>'; } catch(_) {}
  }
}

/* Derive a 1–2 char monogram for a project tile. A single glyph is a poor
 * recognition cue (the owner's complaint), so we prefer two: initials of the
 * first two whitespace/`-`/`_`/`/`-separated words (e.g. "Machine Learning" →
 * "ML", "arxiv-papers" → "AP"); for a single word, its first two LETTERS
 * ("chatui" → "CH"). CJK names take the FIRST TWO characters as-is (already
 * dense and legible). Falls back to "•" for an empty/symbol-only name. */
function _folderMonogram(name) {
  const s = String(name || '').trim();
  if (!s) return '•';
  // CJK (Han/Hiragana/Katakana/Hangul) — two chars carry meaning; use them raw.
  if (/[\u3040-\u30ff\u3400-\u9fff\uac00-\ud7af]/.test(s)) {
    return Array.from(s).slice(0, 2).join('');
  }
  const words = s.split(/[\s\-_/.]+/).filter(Boolean);
  if (words.length >= 2) {
    return (words[0][0] + words[1][0]).toUpperCase();
  }
  const w = words[0] || s;
  return w.slice(0, 2).toUpperCase();
}

/* Deterministic tile background for a project whose owner never picked a color.
 * Without this, every uncolored folder fell back to the single `var(--accent)`,
 * so N uncolored projects were one indistinguishable color block — defeating
 * the at-a-glance recognition the rail exists for. We derive a STABLE hue by
 * hashing the folder id (falling back to name) and spreading it around the
 * wheel, at a fixed pastel S/L that reads on both dark and parchment themes.
 * Same folder → same color across every render/session (hash is pure). */
function _folderColor(f) {
  if (f && f.color) return f.color;
  const key = String((f && (f.id || f.name)) || '');
  if (!key) return 'var(--accent)';
  let h = 0;
  for (let i = 0; i < key.length; i++) {
    h = (h * 31 + key.charCodeAt(i)) >>> 0;
  }
  return `hsl(${h % 360} 52% 55%)`;
}

function _renderFolderTabsInner(tabsEl, folders, activeFolderId, allConvs) {
  const safeFolders = folders || [];
  const safeConvs = allConvs || [];

  /* ── Zero-folder degradation ──
   * A user who never made a folder must NOT be forced into a two-pane rail
   * layout. With 0 folders the rail is hidden entirely (single-column list,
   * exactly as before) and only the discreet "+ New folder" quick-add entry
   * point shows. The rail materializes once ≥1 folder exists. The sidebar
   * `.has-rail` class drives the CSS grid/flex split. */
  const sidebarEl = tabsEl.closest('.sidebar') || document.getElementById('sidebar');
  const hasRail = safeFolders.length > 0;
  if (sidebarEl) sidebarEl.classList.toggle('has-rail', hasRail);
  // Persist the width hint + sync html[data-rail] so the NEXT load paints at
  // the right width (zero CLS), and so an appear/disappear this session is
  // reflected on the root immediately.
  _persistRailHint(hasRail);
  if (!hasRail) {
    tabsEl.innerHTML = '';
    _lastFolderTabsHash = '';
    _lastFolderTabsContentHash = '';
    _lastFolderTabsStructHash = '';
    return;
  }
  tabsEl.style.display = '';

  // Compute counts per folder + uncategorized
  const folderIds = new Set(safeFolders.map(f => f.id));
  const countMap = {};
  let uncategorizedCount = 0;
  for (const c of safeConvs) {
    if (c.folderId && folderIds.has(c.folderId)) {
      countMap[c.folderId] = (countMap[c.folderId] || 0) + 1;
    } else {
      uncategorizedCount++;
    }
  }

  // Compute latest activity time per folder for sorting
  const lastActiveMap = {};
  for (const c of safeConvs) {
    if (c.folderId && folderIds.has(c.folderId)) {
      const ts = c.updatedAt || c.createdAt || 0;
      if (!lastActiveMap[c.folderId] || ts > lastActiveMap[c.folderId]) {
        lastActiveMap[c.folderId] = ts;
      }
    }
  }

  // Detect which folders have actively streaming/generating conversations
  const streamingFolderIds = new Set();
  for (const c of safeConvs) {
    if (!c.folderId || !folderIds.has(c.folderId)) continue;
    const isStreaming = convIsBusy(c) || c._translating || c._memoryPrefetching;
    if (isStreaming) streamingFolderIds.add(c.folderId);
  }

  /* Reflect the persisted collapsed/expanded choice on the sidebar every
   * render (cheap class toggle, outside the structural fast path so it always
   * self-heals to the stored value). */
  const railCollapsed = _readRailCollapsed();
  if (sidebarEl) sidebarEl.classList.toggle('rail-collapsed', railCollapsed);

  // Split hash: content hash (folders/counts/names) vs active-tab hash
  // When only the active tab changes, skip full DOM rebuild and just swap .active class
  const streamKey = [...streamingFolderIds].sort().join(',');
  const structHash = `U${uncategorizedCount}|${safeFolders.map(f=>`${f.id}|${f.name}|${f.color||''}|${JSON.stringify(f.projectPaths || f.projectPath || [])}|${JSON.stringify(f.readOnlyPaths || [])}|${lastActiveMap[f.id]||0}|${countMap[f.id]||0}`).join(',')}`;
  const contentHash = `${structHash}|S${streamKey}`;
  const fullHash = `${activeFolderId||''}|${contentHash}`;
  if (fullHash === _lastFolderTabsHash) return;

  const contentChanged = contentHash !== _lastFolderTabsContentHash;
  const structChanged = structHash !== _lastFolderTabsStructHash;
  _lastFolderTabsHash = fullHash;
  _lastFolderTabsContentHash = contentHash;
  _lastFolderTabsStructHash = structHash;

  // Fast path: only active tab and/or streaming state changed — update classes in-place, no DOM rebuild
  if (!structChanged) {
    const btns = tabsEl.querySelectorAll('.folder-tab[data-folder-id]');
    btns.forEach(btn => {
      const fid = btn.dataset.folderId;
      btn.classList.toggle('active', fid === (activeFolderId || ''));
      const dot = btn.querySelector('.folder-tab-dot');
      if (dot) dot.classList.toggle('streaming', streamingFolderIds.has(fid));
    });
    return;
  }

  /* Rank by the project's most recent SIGNAL, counting creation as one: a
   * just-created project has no conversations yet, so activity-only ranking
   * scored it 0 and buried it at the rail bottom — exactly when the user is
   * about to file something into it. */
  const _folderSortTs = (f) => Math.max(lastActiveMap[f.id] || 0, f.createdAt || 0);
  const sortedFolders = [...safeFolders].sort((a, b) => _folderSortTs(b) - _folderSortTs(a) || (a.order || 0) - (b.order || 0));

  /* ── Vertical project rail ──
   * Each project is a full-width ROW (dot + name + count) so names of any
   * length align into clean columns — no ragged wrap. The rail scrolls
   * vertically when it overflows; there is no more +N expand toggle.
   * Row DOM contract is UNCHANGED from the pill era: `.folder-tab` with
   * `data-folder-id` (empty string = 未分类), an inner `.folder-tab-dot`
   * (streaming pulse) and `.folder-tab-name`, so _initFolderTabs' click /
   * context-menu / long-press / drag-drop handlers all keep working. */
  const railTitle = escapeHtml(t('sidebar.projects'));
  const collapseTip = railCollapsed ? escapeHtml(t('sidebar.expandRail')) : escapeHtml(t('sidebar.collapseRail'));
  let html = '';
  html += `<div class="project-rail-head">`;
  html += `<span class="project-rail-title">${railTitle}</span>`;
  html += `<button class="project-rail-collapse" title="${collapseTip}" aria-label="${collapseTip}">`;
  html += `<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="15 18 9 12 15 6"/></svg>`;
  html += `</button></div>`;
  html += '<div class="project-rail-list">';

  // "未分类" row — conversations not in any folder (uses the inbox glyph as its "dot")
  const ucBadge = uncategorizedCount > 0 ? `<span class="folder-tab-count">${uncategorizedCount}</span>` : '';
  html += `<button class="folder-tab folder-tab-uncat${!activeFolderId ? ' active' : ''}" data-folder-id="" title="${escapeHtml(t('sidebar.uncategorized'))}">`;
  html += `<span class="folder-tab-dot folder-tab-inbox-dot"><svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="22 12 16 12 14 15 10 15 8 12 2 12"/><path d="M5.45 5.11L2 12v6a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2v-6l-3.45-6.89A2 2 0 0 0 16.76 4H7.24a2 2 0 0 0-1.79 1.11z"/></svg></span>`;
  html += `<span class="folder-tab-name">${escapeHtml(t('sidebar.uncategorized'))}</span>${ucBadge}</button>`;

  // Project rows
  for (const f of sortedFolders) {
    const fcolor = escapeHtml(_folderColor(f));
    const fname = escapeHtml(f.name);

    const roots = folderDefaultProjectPaths(f.id);
    const summary = roots.length ? t('folder.settings.rootCount', { n: roots.length }) : t('folder.settings.noRoots');
    const folderTip = escapeHtml([f.name, summary, ...roots].join('\n'));
    const isActive = activeFolderId === f.id;
    const cnt = countMap[f.id] || 0;
    const badge = cnt > 0 ? `<span class="folder-tab-count">${cnt}</span>` : '';
    const dotStreaming = streamingFolderIds.has(f.id) ? ' streaming' : '';
    const mono = _folderMonogram(f.name);
    html += '<div class="folder-tab-row">';
    html += `<button class="folder-tab${isActive ? ' active' : ''}" data-folder-id="${escapeHtml(f.id)}" title="${folderTip}" aria-label="${escapeHtml(f.name + ': ' + summary)}">`;
    html += `<span class="folder-tab-dot${dotStreaming}" style="background:${fcolor}" data-initial="${escapeHtml(mono)}" data-mono-len="${mono.length}"></span>`;
    html += `<span class="folder-tab-copy"><span class="folder-tab-name">${fname}</span><span class="folder-tab-summary">${escapeHtml(summary)}</span></span>${badge}`;
    html += `</button></div>`;
  }
  html += '</div>';
  // Footer "+ New project" row — always visible at the rail bottom.
  html += `<button class="folder-tab folder-tab-add" title="${escapeHtml(t('sidebar.newFolder'))}">`;
  html += `<span class="folder-tab-dot folder-tab-add-dot"><svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg></span>`;
  html += `<span class="folder-tab-name">${escapeHtml(t('sidebar.newFolder'))}</span>`;
  html += `</button>`;
  tabsEl.innerHTML = html;

  mountFolderConfigControls(tabsEl, t('folder.settings.title'));
}

/* ═══════════════════════════════════════════════════════════════════
 * PERF: Windowed conversation-list rendering.
 *
 * Rendering all N conversation rows synchronously (innerHTML of the full
 * `filtered` set) was the dominant cold-load long-task: with a couple
 * thousand convs it produced >2000 DOM children, ~65k total page nodes,
 * 700ms+ of forced reflow, and starved LCP. Instead we render only the
 * first page up-front and append further pages as a bottom sentinel
 * scrolls into the #convList viewport.
 *
 * Correctness contract with the three fast paths in renderConversationList:
 *   • The active conv is always forced into the FIRST page (see
 *     _renderConvWindow) so its .active indicator / status dot never
 *     depends on a row that hasn't been scrolled into existence.
 *   • The status-only fast path SKIPS rows not currently in the DOM
 *     (windowed-out) instead of bailing to a full rebuild — windowed rows
 *     read live status via _buildConvItemHTML when later appended.
 *   • _swapActiveConvItem already falls back to a full rebuild when its
 *     target row isn't found, which re-windows from the top.
 * ═══════════════════════════════════════════════════════════════════ */
const _CONV_WINDOW_PAGE = 50;          // rows rendered per page
const _CONV_WINDOW_PREFETCH_PX = 600;  // append the next page this far before the sentinel is reached
let _convVirtual = { observer: null, sentinel: null };

/** Disconnect any active windowing observer and drop the sentinel ref. */
function _teardownConvVirtual() {
  if (_convVirtual.observer) {
    try { _convVirtual.observer.disconnect(); } catch (_e) { /* ignore */ }
    _convVirtual.observer = null;
  }
  _convVirtual.sentinel = null;
}

/**
 * Build the render plan for `filtered`: a flat list of items, each either a
 * date-group header, a conversation row, or the collapsed-"older" toggle.
 * `filtered` is recency-sorted so each date bucket is one contiguous run.
 * The ">30 days" bucket is collapsed behind a toggle unless expanded (or the
 * active conv lives in it, or it's the ONLY populated group — in those cases
 * it's force-expanded so its rows are always visible and clickable).
 *
 * @returns {Array<{type:'header'|'conv'|'older'|'older-collapse', key?:string, conv?:object, count?:number}>}
 */
function _buildConvPlan(filtered) {
  /* Per-group row counts so each header shows its size. */
  const counts = {};
  for (const c of filtered) {
    const key = _convDateGroupKey(c.updatedAt || c.createdAt);
    counts[key] = (counts[key] || 0) + 1;
  }
  /* Keep the active conv's group always expanded so its row never hides. */
  const activeKey = activeConvId
    ? (() => { const a = filtered.find(c => c.id === activeConvId); return a ? _convDateGroupKey(a.updatedAt || a.createdAt) : null; })()
    : null;

  /* Never auto-collapse the ONLY populated group. The "older" (>30d) bucket
   * starts collapsed, but for a user whose conversations are ALL older than 30
   * days that would hide every row behind a single collapsed header — the
   * sidebar looks empty and clicks land on nothing (no .conv-item is rendered).
   * When a single group holds all the rows, force it expanded regardless of
   * its remembered collapsed state, so there is always something to click. */
  const _soleGroupKey = Object.keys(counts).length === 1 ? Object.keys(counts)[0] : null;

  /* Bucket rows by group so each section header emits EXACTLY ONCE in
   * canonical rank order. (The contiguous-run walk would emit a duplicate
   * header whenever the incoming order isn't perfectly group-contiguous —
   * _convSorter now guarantees that, but bucketing makes the plan correct
   * for ANY input order, e.g. search results or the incremental fast path.) */
  const buckets = new Map();  // key -> conv[]
  for (const c of filtered) {
    const key = _convDateGroupKey(c.updatedAt || c.createdAt);
    let rows = buckets.get(key);
    if (!rows) { rows = []; buckets.set(key, rows); }
    rows.push(c);
  }
  const orderedKeys = [...buckets.keys()].sort((ka, kb) =>
    (_CONV_GROUP_RANK[ka] ?? _CONV_GROUP_RANK.older) - (_CONV_GROUP_RANK[kb] ?? _CONV_GROUP_RANK.older));

  /** @type {Array<{type:'header'|'conv', key?:string, count?:number, collapsed?:boolean, conv?:object}>} */
  const plan = [];
  for (const key of orderedKeys) {
    /* An explicit user toggle always wins; the active-conv / sole-group
     * force-expand only guards the default (never-user-touched) state so a
     * default-collapsed "older" bucket can't hide the whole list on load. */
    const collapsed = _collapsedConvGroups.has(key) &&
      (_userToggledConvGroups.has(key) || (key !== activeKey && key !== _soleGroupKey));
    plan.push({ type: 'header', key, count: buckets.get(key).length, collapsed });
    if (collapsed) continue;   // rows hidden under a collapsed header
    for (const c of buckets.get(key)) plan.push({ type: 'conv', conv: c });
  }
  return plan;
}

/** Render a single plan item to HTML. */
function _planItemHtml(item) {
  if (item.type === 'header') return _convGroupHeaderHtml(item.key, item.count, item.collapsed);
  const c = item.conv;
  return _buildConvItemHTML(c, escapeHtml(_conversationDisplayTitle(
    c.title, t('chat.newConversation'))), "");
}

/**
 * Render `filtered` into `listEl` with bottom-sentinel windowing. Renders
 * the first page (extended downward if needed so the active conv is always
 * included), then lazily appends subsequent pages on scroll. Rows are grouped
 * under date-section headers via the render plan from _buildConvPlan().
 */
function _renderConvWindow(listEl, filtered) {
  _teardownConvVirtual();

  const plan = _buildConvPlan(filtered);

  /* Ensure the active row is within the initial window so its .active
   * class + status dot are present immediately (sorted recent-first means
   * this is almost always near the top, but a click on an old conv can be
   * deep). Index is into the PLAN (headers shift positions). */
  let firstEnd = _CONV_WINDOW_PAGE;
  if (activeConvId) {
    const ai = plan.findIndex(it => it.type === 'conv' && it.conv.id === activeConvId);
    if (ai >= firstEnd) firstEnd = ai + 1;
  }
  firstEnd = Math.min(firstEnd, plan.length);

  let html = "";
  for (let i = 0; i < firstEnd; i++) {
    html += _planItemHtml(plan[i]);
  }
  listEl.innerHTML = html;

  /* Everything fits in the first window — no sentinel/observer needed. */
  if (firstEnd >= plan.length) return;

  let cursor = firstEnd;
  const sentinel = document.createElement('div');
  sentinel.className = 'conv-window-sentinel';
  sentinel.setAttribute('aria-hidden', 'true');
  listEl.appendChild(sentinel);
  _convVirtual.sentinel = sentinel;

  const obs = new IntersectionObserver((entries) => {
    /* Ignore stale callbacks from a sentinel that's been torn down. */
    if (_convVirtual.sentinel !== sentinel) return;
    if (!entries.some(e => e.isIntersecting)) return;

    const end = Math.min(cursor + _CONV_WINDOW_PAGE, plan.length);
    let frag = "";
    for (let i = cursor; i < end; i++) {
      frag += _planItemHtml(plan[i]);
    }
    sentinel.insertAdjacentHTML('beforebegin', frag);
    cursor = end;

    if (cursor >= plan.length) {
      _teardownConvVirtual();
      return;
    }
    /* The sentinel may still be inside the prefetch zone after the append
     * (true→true gives no new callback). Re-observe on the next frame to
     * force a fresh intersection check so paging chains until the sentinel
     * is pushed below the prefetch margin. */
    obs.unobserve(sentinel);
    requestAnimationFrame(() => {
      if (_convVirtual.sentinel === sentinel && _convVirtual.observer === obs) {
        obs.observe(sentinel);
      }
    });
  }, { root: listEl, rootMargin: `0px 0px ${_CONV_WINDOW_PREFETCH_PX}px 0px` });

  obs.observe(sentinel);
  _convVirtual.observer = obs;
}


/* ── C3/C4 — global keyset pagination of the sidebar window ─────────────
 * The top-N sidebar window (Epic D4) is a performance floor, not a ceiling:
 * conversations that sort past it must stay REACHABLE. While the server
 * total exceeds what is loaded, a "N earlier · Load more" affordance hangs
 * below the windowed list (CSS at styles.css .conv-load-more); clicking it —
 * or scrolling it into view — fetches the next keyset page
 * (Api.conversations.listPage) and merges it via mergeConversationCatalogRows. */
let _loadingMoreGlobalConvs = false;

// Search opens can add isolated, much older shells; they are not a page boundary.
let _globalConvPageBoundary = null;
function _oldestGlobalConvBoundary(rows) {
  let boundary = null;
  for (const c of rows) {
    if (!c?.id) continue;
    const ts = c.updatedAt || c.createdAt || 0;
    if (!boundary || ts < boundary.ts || (ts === boundary.ts && c.id < boundary.id)) {
      boundary = { ts, id: c.id };
    }
  }
  return boundary;
}

/* True only for the GLOBAL list (not a folder view, not search) when the
 * server reports more conversations than are currently in memory. */
function _hasMoreGlobalConvs() {
  if (typeof getActiveFolderId === 'function' && getActiveFolderId()) return false;
  const total = typeof getServerTotalCount === 'function' ? getServerTotalCount() : null;
  if (!Number.isFinite(total)) return false;
  return total > conversations.length;
}

function _unloadedGlobalConvCount() {
  const total = typeof getServerTotalCount === 'function' ? getServerTotalCount() : null;
  if (!Number.isFinite(total)) return 0;
  return Math.max(0, total - conversations.length);
}

/* Append the load-more affordance to `listEl` (no-op when caught up). */
function _appendLoadMoreAffordance(listEl) {
  if (!listEl || !_hasMoreGlobalConvs()) return;
  const n = _unloadedGlobalConvCount();
  const btn = document.createElement('button');
  btn.type = 'button';
  btn.className = 'conv-load-more';
  btn.textContent = (typeof t === 'function'
    ? t('sidebar.loadMoreEarlier')
    : '{n} earlier conversations not loaded · Load more').replace('{n}', String(n));
  btn.addEventListener('click', () => { loadMoreGlobalConvs(); });
  listEl.appendChild(btn);
  /* C3: scrolling the affordance into view auto-loads (same handler as the
   * click). The window sentinel pages IN-MEMORY rows; this pages the SERVER
   * once the in-memory rows run out. */
  if (typeof IntersectionObserver === 'function') {
    const obs = new IntersectionObserver((entries) => {
      if (!entries.some(e => e.isIntersecting)) return;
      obs.disconnect();
      loadMoreGlobalConvs();
    }, { root: listEl, rootMargin: '0px 0px 200px 0px' });
    obs.observe(btn);
  }
}

/* Fetch the next keyset page (cursor = oldest in-memory conv) and merge it. */
async function loadMoreGlobalConvs() {
  if (_loadingMoreGlobalConvs || !_hasMoreGlobalConvs()) return;
  _loadingMoreGlobalConvs = true;
  try {
    const boundary = _globalConvPageBoundary || _oldestGlobalConvBoundary(conversations);
    if (!boundary) return;
    const data = await Api.conversations.listPage(boundary.ts, boundary.id, 200);
    const rows = (data && (data.conversations || data.items)) || [];
    if (rows.length && typeof mergeConversationCatalogRows === 'function') {
      const added = mergeConversationCatalogRows(rows);

      _globalConvPageBoundary = _oldestGlobalConvBoundary(rows) || boundary;
      if (added > 0) renderConversationList();
    }
  } catch (e) {
    console.warn('[sidebar] loadMoreGlobalConvs failed:', e && e.message);
  } finally {
    _loadingMoreGlobalConvs = false;
  }
}

function renderConversationList() {

  runtimeScope.presenceRefresh?.();
  const listEl = document.getElementById("convList"),
    statsEl = document.getElementById("sidebarSearchStats");
  if (!sidebarSearchQuery) {
    const _wasSearching = !!_lastRenderedSearchQuery;

    _sidebarSearchController.clear();
    _lastRenderedSearchQuery = "";   // reset when exiting search mode
    statsEl.classList.remove("visible");
    const all = conversations.filter((c) =>
      (runtimeScope.ConversationTurnRead?.ordered?.(c)?.length || 0) > 0
      || (c._serverTurnCount || 0) > 0 || c._turnSnapshotRequired);

    const folders = typeof getFolders === 'function' ? getFolders() : [];
    const _activeFolderId = typeof getActiveFolderId === 'function' ? getActiveFolderId() : null;
    const foldersReady = typeof areFoldersLoaded === 'function' ? areFoldersLoaded() : true;

    const folderHash = folders.map(f => `${f.id}|${f.name}|${f.order}|${f.color||''}`).join(",");
    /* ── Render folder tabs (always, regardless of hash — tab visibility may change) ── */
    renderFolderTabs(folders, _activeFolderId, all);

    /* ── Filter by active folder tab (done BEFORE hashing so the hash and the
     *    in-place fast-path both operate on the actually-visible row set) ── */
    let filtered = all;
    if (_activeFolderId) {
      // Specific folder selected — show only its conversations
      const activeFolder = folders.find(f => f.id === _activeFolderId);
      if (!activeFolder) { // folder was deleted while viewing it
        if (typeof setActiveFolderId === 'function') setActiveFolderId(null);
        return;
      }
      filtered = all.filter(c => c.folderId === _activeFolderId);
    } else if (folders.length > 0) {
      // Default "未分类" view — show only conversations NOT in any folder
      const folderIds = new Set(folders.map(f => f.id));
      filtered = all.filter(c => !c.folderId || !folderIds.has(c.folderId));
    } else if (!foldersReady) {
      // Folders not yet loaded — FAIL OPEN: show every conversation. Hiding a
      // conv that carries a folderId behind a transient (or failed) folder load
      // makes real, server-present conversations invisible — the exact "I lose
      // conversations" symptom. A brief flash of a foldered conv in the
      // uncategorized view is strictly better than dropping it; once folders
      // load the normal branch re-partitions it correctly.
      filtered = all;
    }
    // else: folders loaded and empty — show everything (no folders exist)

    const coordinatorId = document.querySelector('#projectCoordinatorEntry [data-coordinator-id]')?.dataset.coordinatorId;
    if (coordinatorId) filtered = filtered.filter(c => c.id !== coordinatorId);

    /* ── Split hash: struct (row identity/order/title/date/folder) vs status
     *    (active / streaming / translating / memory-prefetch / awaiting-human).
     *    When only status changed we patch each row's .active class + dot +
     *    status tag IN PLACE — no innerHTML rebuild, no full reparse/relayout
     *    of the sidebar (the dominant long-task cost during a send's
     *    translate→stream→done lifecycle). Mirrors the folder-tab fast path. ── */
    /* DBG: per-row action buttons (copy-conv-ID) are baked into the row HTML
     * by _buildConvItemHTML under the debug flag — include it in the struct
     * hash or toggling debug mode in Settings early-returns here and the
     * buttons only appear on the next full page load. */
    const _structHash = `AF${_activeFolderId||''}|FL${foldersReady?1:0}|DBG${(typeof _featureFlags !== 'undefined' && _featureFlags.debug_mode)?1:0}|CG${[..._collapsedConvGroups].sort().join('.')}|F${folderHash}|` +
      filtered.map(c => `${c.id}|${c.title}|${c.updatedAt||""}|${c.folderId||""}|${(c.projectSummary && c.projectSummary.text) ? "S" : ""}`).join("\n");
    const _statusHash = filtered.map(c => {
      const f = _convStatusFlags(c);
      return `${c.id===activeConvId?1:0}${f.streaming?1:0}${f.translating?1:0}${f.memoryPrefetching?1:0}${f.awaitingHuman?1:0}${f.waiting?1:0}${f.errored?1:0}${f.incomplete?1:0}${f.unconfirmed?1:0}${f.rateLimited?1:0}${f.needsReview?1:0}|${f.background?.signature || ''}`;
    }).join(",");
    const _fullHash = `${_structHash}|||${_statusHash}`;
    if (_fullHash === _lastConvListHash) return;

    /* Coming out of search mode the DOM holds search-result rows (different
     * set/order/snippets) — force a full rebuild even if struct hash matches. */
    if (_wasSearching) _lastConvStructHash = "\u0000force-rebuild";
    const _structChanged = _structHash !== _lastConvStructHash;
    _lastConvListHash = _fullHash;
    _lastConvStructHash = _structHash;

    /* ── Fast path: only status changed → patch existing rows in place. ── */
    if (!_structChanged && filtered.length > 0 &&
        listEl.firstElementChild && !listEl.querySelector('.folder-view-empty')) {
      for (const c of filtered) {
        const row = listEl.querySelector(`.conv-item[data-conv-id="${CSS.escape(c.id)}"]`);
        /* Windowed rows not yet scrolled into view aren't in the DOM — skip
         * them (they pick up live status when appended) rather than bailing
         * to a full rebuild on every status tick. Struct-hash equality
         * guarantees the rendered rows are an exact prefix of `filtered`,
         * so a missing row always means "windowed out", never "desynced". */
        if (!row) continue;
        _applyConvItemStatus(row, c);
      }
      /* Keep _lastActiveConvId in sync so _swapActiveConvItem stays O(1). */
      _lastActiveConvId = activeConvId;
      return;
    }

    let listHtml = null;  // non-null only for the empty / special states below

    /* ── Empty state ── */
    if (filtered.length === 0 && (_activeFolderId || folders.length > 0)) {
      const isUncategorized = !_activeFolderId;
      const emptyIcon = isUncategorized
        ? `<svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" style="opacity:0.3;margin-bottom:8px"><polyline points="22 12 16 12 14 15 10 15 8 12 2 12"/><path d="M5.45 5.11L2 12v6a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2v-6l-3.45-6.89A2 2 0 0 0 16.76 4H7.24a2 2 0 0 0-1.79 1.11z"/></svg>`
        : `<svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" style="opacity:0.3;margin-bottom:8px"><path d="M22 19a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h5l2 3h9a2 2 0 0 1 2 2z"/></svg>`;
      const emptyText = isUncategorized ? t('sidebar.allCategorized') : t('sidebar.folderEmpty');
      const emptyHint = isUncategorized
        ? t('sidebar.newChatAppear')
        : t('sidebar.clickNewChat');
      listHtml = `<div class="folder-view-empty">${emptyIcon}` +
        `<div style="font-size:12px;color:var(--text-tertiary)">${emptyText}</div>` +
        `<div style="font-size:11px;color:var(--text-tertiary);opacity:0.6;margin-top:4px">${emptyHint}</div>` +
        `</div>`;
    }

    /* ── Render: the empty / special state goes through a plain innerHTML
     *    assignment; the normal (possibly large) list is windowed so the DOM
     *    node count and synchronous build cost stay bounded regardless of how
     *    many thousands of conversations exist. ── */
    if (listHtml !== null) {
      _teardownConvVirtual();
      listEl.innerHTML = listHtml;
    } else {
      _renderConvWindow(listEl, filtered);
      /* C3/C4: global list only — hang the keyset "load earlier" affordance
       * below the windowed rows (folder views filter a client-side subset,
       * so a global page count would mislead there). */
      if (!_activeFolderId) _appendLoadMoreAffordance(listEl);
    }
    /* Keep _lastActiveConvId in sync after a full rebuild so
     * _swapActiveConvItem can do O(1) swaps on subsequent switches. */
    _lastActiveConvId = activeConvId;
  } else {
    const query = sidebarSearchQuery;

    _lastRenderedSearchQuery = query;
    const local = searchByTitle(query).slice(0, 500).map(hit => ({
      ...hit, id: hit.conv.id, conversation: hit.conv,
    }));
    // Only settled catalog identity/title/revision changes invalidate search;
    // streaming presentation frames do not issue requests.
    const fingerprint = conversations.map(c => `${c.id}:${c.title}:${c._serverRev || 0}`).join('|');
    _sidebarSearchController.setQuery(query, local, fingerprint);
    refreshBackgroundConversationStatuses(
      _sidebarSearchController.snapshot().items.map(item => item.id),
    );
  }
}

function _renderSearchResults(results, query, listEl, statsEl, isPartial) {
  /* Search replaces the whole list DOM — stop any list-mode windowing
   * observer so it can't append conv rows into the search results. */
  _teardownConvVirtual();
  statsEl.classList.add("visible");
  const suffix = isPartial ? ` <span class="search-loading">${escapeHtml(t("sidebar.searching"))}</span>` : "";
  const countText = t(results.length !== 1 ? "sidebar.searchResults" : "sidebar.searchResult", { n: results.length });
  statsEl.innerHTML = `${escapeHtml(countText)}${suffix}`;
  if (results.length === 0 && isPartial) {
    listEl.innerHTML = `<div class="sidebar-search-empty"><div class="sidebar-search-empty-icon"></div>${escapeHtml(t("sidebar.searching"))}</div>`;
    _lastConvListHash = "";
    return;
  }
  if (results.length === 0) {
    /* split/join for literal {q} substitution — avoids $-pattern
     * interpretation in String.replace and keeps the query HTML-escaped. */
    const noMatch = escapeHtml(t("sidebar.searchNoMatches"))
      .split("{q}")
      .join(`<strong>${escapeHtml(query)}</strong>`);
    listEl.innerHTML = `<div class="sidebar-search-empty"><div class="sidebar-search-empty-icon"></div>${noMatch}</div>`;
    _lastConvListHash = "";
    return;
  }
  const items = results.map(
    ({ conv: c, matchField, matchSnippet, matchRole }) => {
      const tHtml =
        matchField === "title"
          ? highlightMatch(_conversationDisplayTitle(
            c.title, t('chat.newConversation')), query)
          : escapeHtml(_conversationDisplayTitle(
            c.title, t('chat.newConversation')));
      let snip = "";
      if (matchSnippet) {
        const ico = "";
        /* ID match: no role prefix ("You:"/"Claude:") — snippet is the ID itself. */
        if (matchField === "id") {
          snip = `<div class="conv-item-snippet">${highlightMatch(matchSnippet, query)}</div>`;
        } else {
          const rl = matchRole === "user" ? t("sidebar.searchRoleYou") : t("sidebar.searchRoleAssistant");
          snip = `<div class="conv-item-snippet">${ico} ${rl}: ${highlightMatch(matchSnippet, query)}</div>`;
        }
      }
      return _buildConvItemHTML(c, tHtml, snip);
    },
  );
  const newHtml = items.join("");
  if (newHtml === _lastConvListHash) return;
  _lastConvListHash = newHtml;
  listEl.innerHTML = newHtml;
}

/* PERF: static action-button SVGs hoisted to module scope — these never
 * change per row, so building them once instead of per-conv shrinks the
 * per-item string work on every full rebuild. */
const _CONV_DEL_SVG = `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 6h18"/><path d="M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6"/><line x1="10" y1="11" x2="10" y2="17"/><line x1="14" y1="11" x2="14" y2="17"/></svg>`;
const _CONV_CP_SVG = `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="9" y="9" width="13" height="13" rx="2" ry="2"/><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/></svg>`;
const _CONV_DUP_SVG = `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="8" y="8" width="14" height="14" rx="2" ry="2"/><path d="M4 16c-1.1 0-2-.9-2-2V4c0-1.1.9-2 2-2h10c1.1 0 2 .9 2 2"/></svg>`;
