  /* "View history" — only meaningful when snapshots exist. */
  const histItem = document.getElementById("mobileCompactHistory");
  if (histItem) {
    const hasHistory = !!(summary && summary.compactions > 0);
    histItem.style.display = hasHistory ? "" : "none";
  }
